import re

class YamlError(Exception):
    def __init__(self, message, line=None, col=None):
        super().__init__(message)
        self.message = message
        self.line = line
        self.col = col

# Simple YAML subset parser + emitter used for ast-grep config / rules / tests / snapshots.

def _strip_comment(s):
    # strip comments outside quotes, preceded by whitespace or start
    i=0; quote=None
    while i < len(s):
        c=s[i]
        if quote:
            if c==quote:
                # doubled single
                if quote=="'" and i+1<len(s) and s[i+1]=="'":
                    i+=2; continue
                quote=None
            elif quote=='"' and c=='\\':
                i+=1
        else:
            if c in "'\"": quote=c
            elif c=='#' and (i==0 or s[i-1] in ' \t'):
                return s[:i].rstrip()
        i+=1
    return s.rstrip()

def _plain_scalar(s):
    s=s.strip()
    if s=='' or s in ('~','null','Null','NULL'):
        return None
    if s in ('true','True','TRUE'):
        return True
    if s in ('false','False','FALSE'):
        return False
    # numbers: avoid converting things like 001? yaml int would; keep simple
    if re.fullmatch(r'[-+]?\d+', s):
