    return s

_ESCAPES={'0':'\0','a':'\a','b':'\b','t':'\t','\t':'\t','n':'\n','v':'\v','f':'\f','r':'\r','e':'\x1b',' ':' ','"':'"','/':'/','\\':'\\'}
def _decode_double(s):
