def _needs_quote(s):
    if s=='' : return True
    if s.strip()!=s: return True
    if s in ('true','false','null','~','True','False','Null'): return True
    if re.fullmatch(r'[-+]?\d+',s) or re.fullmatch(r'[-+]?(\d+\.\d*|\d*\.\d+)',s): return True
