    if s[0] in '!&*[]{},\'"%@`|>': return True
    if s[0]=='-' and (len(s)==1 or s[1]==' '): return True
    if ': ' in s or s.endswith(':'): return True
    if ' #' in s: return True
    return False

def _scalar_repr(v):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,(int,float)) and not isinstance(v,bool): return str(v)
    s=str(v)
    if '\n' in s:
