        return self.root

class Token:
    __slots__=("text","start","end","type","meta","quote","content_start","content_end","line","col")
    def __init__(self,text,start,end,type,doc,meta=None,quote=None,content_start=None,content_end=None):
        self.text=text; self.start=start; self.end=end; self.type=type; self.meta=meta; self.quote=quote
        self.content_start=content_start; self.content_end=content_end
        self.line,self.col=doc.line_col(start)
    def __repr__(self): return f"Tok({self.type},{self.text!r})"

META_NAME_RE=re.compile(r'^[A-Z_][A-Z0-9_]*$')
def parse_meta_text(txt):
    # returns dict(name,multi,anonymous,display) or None if exact token text is a meta identifier
    if not txt.startswith('$'): return None
    d=0
    while d<len(txt) and txt[d]=='$': d+=1
    rest=txt[d:]
    if d==3 and rest=='':
        return {"name":None,"multi":True,"anonymous":True,"display":"$$$"}
    if d in (1,2,3) and rest and META_NAME_RE.match(rest):
        multi=(d==3)
        anon=rest.startswith('_')
        name=None if anon else rest
        if multi:
            display='$$$'+(rest if not anon else '')
        else:
            display='$'+(rest if not anon else '_')
        return {"name":name,"multi":multi,"anonymous":anon,"display":display}
    return None

OPERATORS=sorted(['===','!==','...','**=','<<=','>>=','&&=','||=','??=','<=>','..=','=>','->','::','?.','??','==','!=','<=','>=','&&','||','++','--','+=','-=','*=','/=','%=','&=','|=','^=','**','<<','>>','..','|>','|','&','^','~',':=','<-','</','/>','?.','::=','->>','===','!=='],key=len,reverse=True)
SINGLE_OPS=set('()[]{}<>,.;:!@#%^&*+-=/|\\?~`')

def tokenize(doc):
    text=doc.text; lang=doc.lang; is_pattern=doc.is_pattern
    toks=[]; i=0; n=len(text)
    html_text_mode=False if lang!='Html' else True
    while i<n:
        ch=text[i]
        if ch in ' \t\r\f\v':
            i+=1; continue
        if ch=='\n':
            i+=1; continue
        # HTML text
        if lang=='Html' and html_text_mode and ch!='<':
            start=i
            while i<n and text[i]!='<': i+=1
            raw=text[start:i]
            if raw.strip():
                # node span includes all raw (tree-sitter text may include leading ws) keep full
                toks.append(Token(raw,start,i,'text',doc))
            continue
        # comments
        if i==0 and text.startswith('#!',i):
            start=i
            while i<n and text[i]!='\n': i+=1
            toks.append(Token(text[start:i],start,i,'comment',doc)); continue
        if lang=='Html' and text.startswith('<!--',i):
            start=i; end=text.find('-->',i+4); i=n if end<0 else end+3
            toks.append(Token(text[start:i],start,i,'comment',doc)); continue
        if lang in ('Haskell',) and text.startswith('{-',i):
            start=i; end=text.find('-}',i+2); i=n if end<0 else end+2
            toks.append(Token(text[start:i],start,i,'comment',doc)); continue
        if text.startswith('/*',i) and lang not in ('Python','Ruby','Bash','Yaml','Haskell'):
            start=i; end=text.find('*/',i+2); i=n if end<0 else end+2
            toks.append(Token(text[start:i],start,i,'comment',doc)); continue
        if text.startswith('//',i) and lang not in ('Python','Ruby','Bash','Yaml','Haskell','Lua','Css','Html'):
            start=i
            while i<n and text[i]!='\n': i+=1
            toks.append(Token(text[start:i],start,i,'comment',doc)); continue
        if ch=='#' and lang in ('Python','Ruby','Bash','Yaml','Elixir','Php','Nix'):
            start=i
            while i<n and text[i]!='\n': i+=1
            toks.append(Token(text[start:i],start,i,'comment',doc)); continue
        if text.startswith('--',i) and lang in ('Lua','Haskell') :
            # --[[ ]] for lua
            start=i
            if lang=='Lua' and text.startswith('--[[',i):
                end=text.find(']]',i+4); i=n if end<0 else end+2
            else:
                while i<n and text[i]!='\n': i+=1
            toks.append(Token(text[start:i],start,i,'comment',doc)); continue
        # HTML mode exits when '<'
        if lang=='Html' and ch=='>':
            toks.append(Token('>',i,i+1,'op',doc)); i+=1; html_text_mode=True; continue
        if lang=='Html' and ch=='<':
            html_text_mode=False
        # Strings
        if ch=='`':
            # template: tokenize pieces always as template structure
            toks.append(Token('`',i,i+1,'template',doc)); i+=1
            chunk_start=i
            while i<n:
                if text[i]=='\\': i+=2; continue
                if text.startswith('${',i):
                    if i>chunk_start: toks.append(Token(text[chunk_start:i],chunk_start,i,'string_content',doc))
                    toks.append(Token('${',i,i+2,'op',doc)); i+=2
                    # tokenize expression until matching } at depth 0, using main loop by setting a marker? We'll recursively tokenize substring? Simplistic inline scanning with brace depth and tokenizing through this function's mechanism would need stack.
                    # Fall back: set a flag state via storing a sub tokenizer over the interpolation segment.
                    depth=1; expr_start=i
                    while i<n and depth>0:
                        if text[i]=='{': depth+=1; i+=1
                        elif text[i]=='}': depth-=1; i+=1 if depth==0 else i+0; i+=0 if depth==0 else 1 if False else 0; 
                        else: i+=1
                        if depth==0: break
                    expr_end=i-1
                    subdoc_tokens=_tokenize_fragment(doc, expr_start, expr_end)
                    toks.extend(subdoc_tokens)
                    toks.append(Token('}',expr_end,expr_end+1,'op',doc)); i=expr_end+1; chunk_start=i; continue
                if text[i]=='`':
                    if i>chunk_start: toks.append(Token(text[chunk_start:i],chunk_start,i,'string_content',doc))
                    toks.append(Token('`',i,i+1,'template',doc)); i+=1; chunk_start=None; break
                i+=1
            continue
        if ch in ('"',"'"):
            # Rust lifetime: 'a not a char if no closing quickly
            if ch=="'" and lang=='Rust':
                # char literal: '\n', 'x'
                if not (i+2<n and text[i+2]=="'" or (i+3<n and text[i+1]=='\\' and text[i+3]=="'") or (i+1<n and text[i+1]=="'")):
                    toks.append(Token("'",i,i+1,'op',doc)); i+=1; continue
            quote=ch; start=i
            triple=text.startswith(quote*3,i)
            if triple:
                cstart=i+3; end=text.find(quote*3,cstart); 
                if end<0: cend=n; i=n
                else: cend=end; i=end+3
            else:
                i+=1; cstart=i
                while i<n:
                    if text[i]=='\\': i+=2; continue
                    if text[i]==quote: break
                    if text[i]=='\n' and lang not in ('Python',): break
                    i+=1
                cend=i
                if i<n and text[i]==quote: i+=1
            toks.append(Token(text[start:i],start,i,'string',doc,quote=quote,content_start=cstart,content_end=cend)); continue
        # pattern/meta & identifiers with $
        if ch=='$' or ch=='_' or ch.isalpha():
            start=i
            # consume $ + identifier chars (also allow many $)
            while i<n and (text[i]=='$' or text[i]=='_' or text[i].isalnum()):
                i+=1
            txt=text[start:i]
            meta=parse_meta_text(txt) if is_pattern else None
            typ='meta' if meta else 'ident'
            # Numbers can't start here
            toks.append(Token(txt,start,i,typ,doc,meta=meta)); continue
        if ch.isdigit():
            start=i
            # number
            if text.startswith(('0x','0X'),i):
                i+=2
                while i<n and (text[i] in '0123456789abcdefABCDEF_'): i+=1
            elif text.startswith(('0b','0B'),i):
                i+=2
                while i<n and text[i] in '01_': i+=1
            elif text.startswith(('0o','0O'),i):
                i+=2
                while i<n and text[i] in '01234567_': i+=1
            else:
                while i<n and (text[i].isdigit() or text[i]=='_'): i+=1
                if i<n and text[i]=='.' and i+1<n and text[i+1].isdigit():
                    i+=1
                    while i<n and (text[i].isdigit() or text[i]=='_'): i+=1
                if i<n and text[i] in 'eE':
                    j=i+1
                    if j<n and text[j] in '+-': j+=1
                    if j<n and text[j].isdigit():
                        i=j
                        while i<n and text[i].isdigit(): i+=1
            while i<n and (text[i].isalpha() or text[i]=='_'): i+=1  # suffix
            toks.append(Token(text[start:i],start,i,'number',doc)); continue
        # operators
        matched=None
        for op in OPERATORS:
            if text.startswith(op,i): matched=op; break
        if matched:
            toks.append(Token(matched,i,i+len(matched),'op',doc)); i+=len(matched); continue
        if ch in SINGLE_OPS:
            toks.append(Token(ch,i,i+1,'op',doc)); i+=1; continue
        # any other single char as op
        toks.append(Token(ch,i,i+1,'op',doc)); i+=1
    return toks

def _tokenize_fragment(doc, start, end):
    # tokenize doc.text[start:end] but produce tokens with absolute positions. Create a temporary doc-like parse by slicing: easier make tokens by invoking tokenize on a shallow copy with substring then offset.
    # Make a minimal object copying doc attributes but text fragment for line_col adjusted later.
    class Fake: pass
    fake=Fake(); fragment=doc.text[start:end]
    # Use SourceDoc but that would recursively call tokenize; create without __init__
    fdoc=SourceDoc.__new__(SourceDoc)
    fdoc.text=fragment; fdoc.lang=doc.lang; fdoc.is_pattern=doc.is_pattern; fdoc.filename=doc.filename
    fdoc.line_starts=[0]
    for ii,ch in enumerate(fragment):
        if ch=='\n': fdoc.line_starts.append(ii+1)
    fdoc.byte_offsets=[0]*(len(fragment)+1)
    toks=tokenize(fdoc)
    # offset tokens
    out=[]
    for t in toks:
        nt=Token.__new__(Token); nt.text=t.text; nt.start=t.start+start; nt.end=t.end+start; nt.type=t.type; nt.meta=t.meta; nt.quote=t.quote
        nt.content_start=(t.content_start+start if t.content_start is not None else None)
        nt.content_end=(t.content_end+start if t.content_end is not None else None)
        nt.line,nt.col=doc.line_col(nt.start)
        out.append(nt)
    return out

class Node:
    __slots__=("coarse","doc","start","end","children","named","token_type","token_text","meta","field","parent","role","attrs")
    def __init__(self,doc,coarse,start,end,children=None,named=True,token_type=None,token_text=None,meta=None,role=None,attrs=None):
        self.doc=doc; self.coarse=coarse; self.start=start; self.end=end; self.children=children or []; self.named=named
        self.token_type=token_type; self.token_text=token_text; self.meta=meta; self.field=None; self.parent=None; self.role=role; self.attrs=attrs or {}
        if children:
            # do not auto adjust start/end if supplied? caller uses node_from_children mostly
            pass
    def text(self):
        return self.doc.text[self.start:self.end]
    def is_leaf(self):
        return not self.children
    def range_dict(self):
        sl,sc=self.doc.line_col(self.start); el,ec=self.doc.line_col(self.end)
        return {"byteOffset":{"start":self.doc.byte_offset(self.start),"end":self.doc.byte_offset(self.end)},"start":{"line":sl,"column":sc},"end":{"line":el,"column":ec}}
    def named_children(self):
        return [c for c in self.children if c.named]
    def leaf_texts(self):
        if self.is_leaf(): return [self.doc.text[self.start:self.end]]
        out=[]
        for c in self.children: out.extend(c.leaf_texts())
        return out
    @property
    def ext_kind(self):
        lang=self.doc.lang; coarse=self.coarse
        if self.is_leaf():
            if self.meta:
                # placeholder kind based on role
                if self.role=='property': return pick_kind(lang, ["property_identifier","field_identifier","identifier"])
                if self.role=='type': return pick_kind(lang, ["type_identifier","identifier"])
                return pick_kind(lang, ["identifier","name"], "identifier")
            tt=self.token_type
            if tt=='ident':
                if is_keyword(lang, self.token_text): return self.token_text
                if self.role=='property': return pick_kind(lang, ["property_identifier","field_identifier","attribute_name","field_name","identifier"])
                if self.role=='type': return pick_kind(lang, ["type_identifier","primitive_type","identifier"])
                # Types in some languages are Capitalized? keep identifier
                return pick_kind(lang, ["identifier","name","variable_name","word"], "identifier")
            if tt=='number':
                txt=self.token_text or ''
                if '.' in txt or 'e' in txt.lower(): return pick_kind(lang, ["float","float_literal","floating_point_literal","number","decimal_literal"], "number")
                return pick_kind(lang, ["integer","integer_literal","int_literal","number","decimal_integer_literal"], "number") if lang=='Python' else pick_kind(lang, ["number","integer","integer_literal","int_literal"], "number")
            if tt=='comment': return "comment"
            if tt=='text': return pick_kind(lang, ["text","raw_text"], "text")
            if tt=='string_content': return pick_kind(lang, ["string_fragment","string_content","string_text","text"], "string_fragment")
            return self.token_text or self.text()
        # internal
        if coarse=='root': return ROOT_KIND.get(lang,"program")
        if coarse=='error': return "ERROR"
        if coarse=='string': return pick_kind(lang, ["string","string_literal","interpreted_string_literal","quoted_string"], "string")
        if coarse=='template_string': return pick_kind(lang, ["template_string","template_literal","string"], "template_string")
        if coarse=='expression_statement': return pick_kind(lang, ["expression_statement","expression","statement"], "expression_statement")
        if coarse=='empty_statement': return pick_kind(lang, ["empty_statement"], "empty_statement")
        if coarse=='block':
            ctx=self.attrs.get('block_context')
            if ctx=='class': return pick_kind(lang, ["class_body","class_block","declaration_list","field_declaration_list","block"], "class_body")
            if lang=='Python': return pick_kind(lang, ["block"], "block")
            return pick_kind(lang, ["statement_block","block","compound_statement"], "statement_block")
        if coarse=='brace':
            if self.attrs.get('pair_like'): return pick_kind(lang, ["object","dictionary","hash","table_constructor","object_literal","map"], "object")
            ctx=self.attrs.get('block_context')
            if ctx=='class': return pick_kind(lang, ["class_body","declaration_list","block"], "class_body")
            return pick_kind(lang, ["statement_block","block","compound_statement","object"], "statement_block")
        if coarse=='object': return pick_kind(lang, ["object","dictionary","hash","table_constructor","composite_literal"], "object")
        if coarse=='arguments': return pick_kind(lang, ["arguments","argument_list"], "arguments")
        if coarse=='parameters': return pick_kind(lang, ["formal_parameters","parameters","parameter_list"], "formal_parameters")
        if coarse=='parameter': return pick_kind(lang, ["required_parameter","parameter","formal_parameter","identifier"], "parameter")
        if coarse=='call': return pick_kind(lang, ["call_expression","call","invocation_expression","method_invocation","function_call_expression"], "call_expression")
        if coarse=='member': 
            if self.attrs.get('op')=='::': return pick_kind(lang, ["scoped_identifier","qualified_name","member_expression","selector_expression"], "member_expression")
            return pick_kind(lang, ["member_expression","attribute","selector_expression","field_expression","field_access","navigation_expression","member_access_expression"], "member_expression")
        if coarse=='subscript': return pick_kind(lang, ["subscript_expression","subscript","index_expression","element_access_expression"], "subscript_expression")
        if coarse=='binary':
            op=self.attrs.get('op','')
            if lang in ('Dart','Kotlin','Scala','Swift'):
                if op in ('+','-'): return pick_kind(lang, ["additive_expression","binary_expression"], "additive_expression")
                if op in ('*','/','%'): return pick_kind(lang, ["multiplicative_expression","binary_expression"], "multiplicative_expression")
            if op in ('==','!=','<','>','<=','>=','===','!==') and lang=='Python': return "comparison_operator"
            if op in ('and','or','&&','||') and lang=='Python': return "boolean_operator"
            return pick_kind(lang, ["binary_expression","binary_operator","infix_expression"], "binary_expression")
        if coarse=='assignment':
            op=self.attrs.get('op','=')
            if op!='=' and op not in (':=',):
                return pick_kind(lang, ["augmented_assignment","compound_assignment_expression","assignment_expression","assignment"], "assignment_expression")
            return pick_kind(lang, ["assignment_expression","assignment","assignment_statement","variable_assignment"], "assignment_expression")
        if coarse=='unary': return pick_kind(lang, ["unary_expression","unary_operator","prefix_expression","not_operator"], "unary_expression")
        if coarse=='update': return pick_kind(lang, ["update_expression","postfix_expression","update_statement"], "update_expression")
        if coarse=='new': return pick_kind(lang, ["new_expression","object_creation_expression","creation_expression"], "new_expression")
        if coarse=='parenthesized': return pick_kind(lang, ["parenthesized_expression","parenthesised_expression"], "parenthesized_expression")
        if coarse=='tuple': return pick_kind(lang, ["tuple","tuple_expression","parenthesized_expression"], "tuple")
        if coarse=='ternary':
            if lang=='JavaScript' or lang in ('TypeScript','Tsx'): return "ternary_expression"
            return pick_kind(lang, ["conditional_expression","ternary_expression","ternary_operator"], "conditional_expression")
        if coarse=='array': return pick_kind(lang, ["array","array_expression","list","array_literal","list_literal","sequence"], "array")
        if coarse=='pair': return pick_kind(lang, ["pair","property_definition","key_value_pair","property","field_definition"], "pair")
        if coarse=='variable_declaration':
            kw=self.attrs.get('keyword','')
            if lang in ('JavaScript','TypeScript','Tsx'):
                return "lexical_declaration" if kw in ('let','const') else "variable_declaration"
            if lang=='Rust': return "let_declaration"
            if lang=='Go': return "var_declaration" if kw=='var' else ("const_declaration" if kw=='const' else "short_var_declaration")
            if lang=='Java': return pick_kind(lang, ["local_variable_declaration","variable_declaration","declaration"], "local_variable_declaration")
            if lang in ('C','Cpp'): return "declaration"
            return pick_kind(lang, ["variable_declaration","lexical_declaration","local_variable_declaration","declaration","variable_declarator"], "variable_declaration")
        if coarse=='variable_declarator': return pick_kind(lang, ["variable_declarator","init_declarator","declarator"], "variable_declarator")
        if coarse=='function_definition':
            if lang=='Rust': return "function_item"
            if lang=='Python': return "function_definition"
            if lang=='Ruby': return "method"
            if lang in ('Java','CSharp'): return pick_kind(lang, ["method_declaration","function_declaration"], "method_declaration")
            return pick_kind(lang, ["function_declaration","function_definition","method_definition","method_declaration","function_item"], "function_declaration")
        if coarse=='arrow_function': return pick_kind(lang, ["arrow_function","lambda","lambda_expression","anonymous_function"], "arrow_function")
        if coarse=='lambda': return pick_kind(lang, ["lambda","lambda_expression","arrow_function","anonymous_function"], "lambda")
        if coarse=='class_definition':
            kw=self.attrs.get('keyword','class')
            if kw=='interface': return pick_kind(lang, ["interface_declaration","trait_item","protocol_declaration"], "interface_declaration")
            if kw=='struct': return pick_kind(lang, ["struct_item","struct_declaration","struct_specifier","class_declaration"], "struct_item")
            if kw=='enum': return pick_kind(lang, ["enum_item","enum_declaration","enum_specifier"], "enum_declaration")
            if kw=='impl': return pick_kind(lang, ["impl_item","implementation"], "impl_item")
            if kw=='trait': return pick_kind(lang, ["trait_item","trait_declaration"], "trait_item")
            if kw in ('module','namespace'): return pick_kind(lang, ["module","namespace_declaration","mod_item"], "module")
            if lang=='Python': return "class_definition"
            return pick_kind(lang, ["class_declaration","class_definition","class_specifier"], "class_declaration")
        if coarse=='if': return pick_kind(lang, ["if_statement","if_expression"], "if_statement")
        if coarse=='for': return pick_kind(lang, ["for_statement","for_expression","for_loop","enhanced_for_statement"], "for_statement")
        if coarse=='while': return pick_kind(lang, ["while_statement","while_expression","while_loop"], "while_statement")
        if coarse=='return': return pick_kind(lang, ["return_statement","return_expression"], "return_statement")
        if coarse=='import':
            kw=self.attrs.get('keyword','import')
            if kw=='package': return pick_kind(lang, ["package_clause","package_declaration"], "package_clause")
            if kw=='use': return pick_kind(lang, ["use_declaration","use"], "use_declaration")
            if kw=='export': return pick_kind(lang, ["export_statement","export_declaration"], "export_statement")
            # python from
            if self.attrs.get('from_import'): return pick_kind(lang, ["import_from_statement","import_statement"], "import_from_statement")
            return pick_kind(lang, ["import_statement","import_declaration","preproc_include"], "import_statement")
        if coarse=='export': return pick_kind(lang, ["export_statement","export_declaration"], "export_statement")
        if coarse=='jsx_element':
            if lang=='Html': return "element"
            return pick_kind(lang, ["jsx_element","element"], "jsx_element")
        if coarse=='jsx_opening': return pick_kind(lang, ["jsx_opening_element","start_tag"], "jsx_opening_element")
        if coarse=='jsx_closing': return pick_kind(lang, ["jsx_closing_element","end_tag"], "jsx_closing_element")
        if coarse=='jsx_self_closing': return pick_kind(lang, ["jsx_self_closing_element","self_closing_tag"], "jsx_self_closing_element")
        if coarse=='cluster': return pick_kind(lang, ["declaration","expression_statement","variable_declaration"], "declaration")
        if coarse=='declaration': return pick_kind(lang, ["declaration","variable_declaration","local_variable_declaration"], "declaration")
        if coarse=='switch': return pick_kind(lang, ["switch_statement","switch_expression","match_expression"], "switch_statement")
        if coarse=='try': return pick_kind(lang, ["try_statement","try_expression"], "try_statement")
        if coarse=='throw': return pick_kind(lang, ["throw_statement","raise_statement"], "throw_statement")
        return coarse

def node_from_children(doc,coarse,children,named=True,attrs=None,role=None):
    if children:
        start=children[0].start; end=children[-1].end
    else:
        start=end=0
    n=Node(doc,coarse,start,end,children,named=named,attrs=attrs,role=role)
    return n
def leaf(doc,tok,role=None):
    named=True
    if tok.type=='op': named=False
    elif tok.type=='template': named=False
    elif tok.type=='ident' and is_keyword(doc.lang,tok.text): named=False
    elif tok.type=='meta': named=True
    return Node(doc,'leaf',tok.start,tok.end,[],named=named,token_type=tok.type,token_text=tok.text,meta=tok.meta,role=role)
def set_parents(node,parent):
    if node is None: return
    node.parent=parent
    for c in node.children: set_parents(c,node)
def all_nodes(node):
    yield node
    for c in node.children: yield from all_nodes(c)

class Parser:
    BINOP_PREC={
        '=':1, ':=':1, '+=':1,'-=':1,'*=':1,'/=':1,'%=':1,'&=`:1' if False else '&=':1,'|=':1,'^=':1,'**=':1,'<<=':1,'>>=':1,'&&=':1,'||=':1,'??=':1,
        '=>':2,
        '??':4,'?:':4,
        '||':5,'or':5,
        '&&':6,'and':6,
        '|':7,'^':8,'&':9,
        '==':10,'!=':10,'===':10,'!==':10,
        '<':11,'>':11,'<=':11,'>=':11,'in':11,'is':11,'instanceof':11,'as':11,'of':11,
        '<<':12,'>>':12,
        '+':13,'-':13,
        '*':14,'/':14,'%':14,
        '**':15,
        '..':4,'..=':4,
        '|>':5, '<=>':11,
    }
    ASSIGN_OPS=set(['=','+=','-=','*=','/=','%=','&=','|=','^=','**=','<<=','>>=','&&=','||=','??=',':='])
    def __init__(self,doc):
        self.doc=doc; self.toks=doc.tokens; self.i=0; self.has_error=False; self.allow_colon=True
    def peek(self,k=0):
        j=self.i+k
        return self.toks[j] if j<len(self.toks) else None
    def cur(self): return self.peek(0)
    def at_eof(self): return self.i>=len(self.toks)
    def advance(self):
        t=self.cur(); self.i+=1; return t
    def accept(self,text):
        t=self.cur()
        if t and t.text==text: self.i+=1; return t
        return None
    def accept_type(self,typ):
        t=self.cur()
        if t and t.type==typ: self.i+=1; return t
        return None
    def last_consumed_line(self):
        if self.i==0: return -1
        return self.toks[self.i-1].line
    def parse_program(self):
        children=self.parse_sequence(set())
        if not children:
            n=Node(self.doc,'root',0,len(self.doc.text),[],named=True); return n
        n=node_from_children(self.doc,'root',children)
        # root should span whole doc if pattern root matches program / file text includes trailing newline? In JS program end may include trailing? original $A match program text included trailing newline for code 'x+y\n' program end at newline (6?) Wait code "x + y\n" program span (0,6) includes \n. Tree-sitter root end is file length perhaps.
        # Set root end to doc len if last child at near end? For all sources root is entire file.
        n.start=0; n.end=len(self.doc.text)
        return n
    def parse_sequence(self, stop_texts, min_col=None, stop_line_col=None):
        children=[]
        while not self.at_eof():
            t=self.cur()
            if t.text in stop_texts: break
            if stop_line_col is not None and children and t.col<=stop_line_col and t.type!='comment':
                break
            if t.text==',':
                children.append(leaf(self.doc,self.advance())); continue
            if t.text==';':
                # empty statement
                semi=leaf(self.doc,self.advance())
                children.append(node_from_children(self.doc,'empty_statement',[semi])); continue
            if t.text in (')',']','}'):
                break
            before=self.i
            stmt=self.parse_statement()
            if stmt is None:
                if self.i==before:
                    if self.at_eof(): break
                    self.has_error=True; stmt=leaf(self.doc,self.advance())
                else:
                    continue
            # semicolon attachment
            if self.cur() and self.cur().text==';':
                semi=leaf(self.doc,self.advance())
                if stmt.coarse in ('call','binary','assignment','member','subscript','unary','update','parenthesized','leaf','array','object','brace','ternary','new','arrow_function','lambda','tuple','string','template_string'):
                    stmt=node_from_children(self.doc,'expression_statement',[stmt,semi])
                else:
                    stmt.children.append(semi); stmt.end=semi.end
            # trailing same line comment attach to make statements with comments
            if self.cur() and self.cur().type=='comment' and self.cur().line==self.doc.line_col(stmt.end-1 if stmt.end>stmt.start else stmt.start)[0]:
                com=leaf(self.doc,self.advance())
                if stmt.coarse=='expression_statement':
                    stmt.children.append(com); stmt.end=com.end
                elif stmt.coarse in ('call','binary','assignment','member','subscript','unary','update','parenthesized','leaf','array','object','ternary','new','string'):
                    stmt=node_from_children(self.doc,'expression_statement',[stmt,com])
                else:
                    # attach as extra child
                    stmt.children.append(com); stmt.end=com.end
            children.append(stmt)
        return children
    # ---------- statements ----------
    def parse_statement(self):
        t=self.cur()
        if t is None: return None
        if t.type=='comment':
            return leaf(self.doc,self.advance())
        if t.text=='{':
            return self.parse_brace_group(block_context='statement')
        if t.text in ('}',')',']'):
            return None
        txt=t.text
        # structured keywords
        if txt in ('if','elif','else','while','for','switch','match','catch','when','with'):
            return self.parse_control()
        if txt in ('try','finally','do'):
            return self.parse_control()
        if txt in ('function','def','func','fn','fun','sub'):
            return self.parse_function_def()
        if txt in ('class','interface','struct','enum','trait','impl','module','namespace','record','object','type') and not (txt=='type' and self.doc.lang in ('JavaScript','Python')):
            # 'type' in Go/Rust declarations etc; TS type alias
            return self.parse_class_def()
        if txt in ('import','from','package','use','using','require'):
            return self.parse_import()
        if txt=='export':
            return self.parse_export()
        if txt in ('return','throw','raise','yield','break','continue','pass','goto','defer','async'):
            # async could prefix function
            if txt=='async':
                nxt=self.peek(1)
                if nxt and nxt.text in ('function','def'):
                    # include async as child of function statement via generic phrase
                    pass
                else:
                    # parse as expression/statement phrase
                    return self.parse_phrase_statement()
            if txt in ('return','throw','raise'):
                kw=leaf(self.doc,self.advance()); children=[kw]
                # optional expr if not terminator and same line
                if self.cur() and self.cur().line==kw_line(self.doc,kw) and self.cur().text not in (';','}',')',']',','):
                    expr=self.parse_expression(); children.append(expr)
                    # phrase clusters after return (rare)
                coarse='return' if txt=='return' else 'throw'
                return node_from_children(self.doc,coarse,children)
            else:
                # break/continue labels optional ident then stmt node
                kw=leaf(self.doc,self.advance()); children=[kw]
                if self.cur() and self.cur().line==kw.line if hasattr(kw,'line') else False: pass
                if self.cur() and self.cur().type in ('ident','meta','number') and self.cur().line==self.doc.line_col(kw.start)[0]:
                    children.append(leaf(self.doc,self.advance()))
                # Create a generic statement; ext kind may not exact but coarse is phrase? Use coarse txt mapped to *_statement in ext fallback returns coarse itself... make course 'expression_statement'? Better a named coarse = txt_statement through ext default? We'll add below generic: coarse=txt+'_statement' ext returns coarse if unknown, which equals tree-sitter for break_statement etc.
                return node_from_children(self.doc, txt+'_statement', children)
        if txt in ('let','const','var','val','local') and self.doc.lang not in ('Go',):
            # Go var handled as declaration too; JS etc
            return self.parse_var_decl()
        if txt in ('let','const','var','val') and self.doc.lang=='Go':
            return self.parse_var_decl()
        if txt=='case' or txt=='default':
            return self.parse_case()
        # declaration keywords maybe modifiers handled phrase
        return self.parse_phrase_statement()
    def parse_case(self):
        children=[]
        kw=leaf(self.doc,self.advance()); children.append(kw)
        if kw.token_text=='case':
            saved=self.allow_colon; self.allow_colon=False
            if self.cur() and self.cur().text not in (':',';'):
                children.append(self.parse_expression())
            self.allow_colon=saved
        if self.cur() and self.cur().text==':': children.append(leaf(self.doc,self.advance()))
        return node_from_children(self.doc,'case_statement',children)
    def parse_export(self):
        kw=leaf(self.doc,self.advance()); children=[kw]
        # default etc is keyword leaf
        # if next is declaration/def/class etc parse as statement child
        t=self.cur()
        if t and t.text in ('class','function','def','let','const','var','interface','type','enum','abstract','async','default'):
            if t.text=='default':
                children.append(leaf(self.doc,self.advance()))
                if self.cur(): children.append(self.parse_statement() if self.cur().text in ('class','function') else self.parse_expression())
            elif t.text=='abstract' or t.text=='async':
                stmt=self.parse_phrase_statement(); children.append(stmt)
            else:
                stmt=self.parse_statement(); children.append(stmt)
        else:
            # phrase items until terminator
            items=self.parse_phrase_items(stop_body=True)
            children.extend(items)
        return node_from_children(self.doc,'export',children,attrs={'keyword':'export'})
    def parse_import(self):
        kw_tok=self.cur(); children=[]; from_import=False
        children.append(leaf(self.doc,self.advance()))
        if kw_tok.text=='from': from_import=True
        # items: phrase until line/semicolon; if '{' brace group handled in expression/cluster
        items=self.parse_phrase_items(stop_body=True)
        children.extend(items)
        return node_from_children(self.doc,'import',children,attrs={'keyword':kw_tok.text,'from_import':from_import})
    def parse_var_decl(self):
        kw_tok=self.advance(); children=[leaf(self.doc,kw_tok)]
        # declarators separated by commas
        while not self.at_eof():
            # declarator: name/destructuring, optional = value or : type etc.
            decl_children=[]
            # name can be identifier/meta, array/object pattern brackets, type phrase
            first=self.parse_expression_or_pattern_name()
            if first: decl_children.append(first)
            # type annotation colon
            if self.cur() and self.cur().text==':':
                # include colon and type as pair? Fold into decl children for matching pattern with full text; simpler create pair handling through colon: append colon and type expr
                decl_children.append(leaf(self.doc,self.advance()))
                if self.cur(): decl_children.append(self.parse_expression())
            if self.cur() and self.cur().text in ('=','+=','-='):
                op=leaf(self.doc,self.advance()); decl_children.append(op)
                if self.cur(): decl_children.append(self.parse_expression())
                decl=node_from_children(self.doc,'variable_declarator',decl_children)
                if len(decl_children)>=3:
                    decl_children[0].field='name'; decl_children[-1].field='value'
            else:
                if len(decl_children)==1:
                    decl=decl_children[0]
                    # for JS let x; tree has variable_declarator wrapping identifier. Wrap.
                    if self.doc.lang in ('JavaScript','TypeScript','Tsx'):
                        decl=node_from_children(self.doc,'variable_declarator',decl_children); decl_children[0].field='name'
                else:
                    decl=node_from_children(self.doc,'variable_declarator',decl_children)
            children.append(decl)
            if self.cur() and self.cur().text==',':
                # comma at same line might be next declarator; tree doesn't include comma as child of lexical? it does as unnamed.
                children.append(leaf(self.doc,self.advance())); continue
            break
        return node_from_children(self.doc,'variable_declaration',children,attrs={'keyword':kw_tok.text})
    def parse_expression_or_pattern_name(self):
        t=self.cur()
        if t is None: return None
        if t.text=='[': return self.parse_primary()  # array pattern as array node
        if t.text=='{': return self.parse_primary()
        if t.type in ('ident','meta'):
            return self.parse_expression()
        return self.parse_expression()
    def parse_function_def(self):
        kw_tok=self.advance(); children=[leaf(self.doc,kw_tok)]
        # optional * (generator) etc
        if self.cur() and self.cur().text=='*': children.append(leaf(self.doc,self.advance()))
        # name
        if self.cur() and self.cur().type in ('ident','meta'):
            name=leaf(self.doc,self.advance()); name.field='name'; children.append(name)
        elif self.cur() and self.cur().text=='(':
            pass # anonymous
        # type params <...>
        if self.cur() and self.cur().text=='<':
            children.append(self.parse_angle_group())
        # parameters
        if self.cur() and self.cur().text=='(':
            params=self.parse_group('(',')', coarse='parameters'); params.field='parameters'; children.append(params)
        # remaining signature (return type etc) until body { or : or => or = or line end
        while self.cur() and self.cur().text not in ('{',':','=>','=',';','}') and self.cur().line==self.doc.line_col(children[-1].start)[0] if False else (self.cur() and self.cur().text not in ('{',':','=>','=',';','}')):
            # This phrase: consume operators/types/comments until body marker. Use wave: break if we have params and current is something that could be body expression on next line? Accept colon type etc: parse one expression item including ':' as pair if needed but TS return `: Type`, python `-> Type`.
            if self.cur().text in (':','->'):
                # for python ':' starts suite - if language python, break
                if self.doc.lang=='Python' and self.cur().text==':': break
                children.append(leaf(self.doc,self.advance())); 
                if self.cur() and self.cur().text not in ('{',':','=>','=',';'): children.append(self.parse_expression())
                continue
            # if we're JS and next is '{' handled
            # Stop if next token is on a different statement line and isn't continuation? Function signatures in one line mostly.
            prev_line=self.doc.line_col(children[-1].end-1 if children[-1].end>children[-1].start else children[-1].start)[0]
            if self.cur().line>prev_line and self.cur().text not in ('{',':'):
                break
            children.append(self.parse_expression())
        body=self.parse_body_after_header(children[-1] if children else None)
        if body is not None:
            if isinstance(body,list): children.extend(body)
            else: body.field='body'; children.append(body)
        return node_from_children(self.doc,'function_definition',children,attrs={'keyword':kw_tok.text})
    def parse_class_def(self):
        kw_tok=self.advance(); children=[leaf(self.doc,kw_tok)]
        # name
        if self.cur() and self.cur().type in ('ident','meta'):
            name=leaf(self.doc,self.advance()); name.field='name'; children.append(name)
        # type params / inheritance phrase until body
        while self.cur() and self.cur().text not in ('{',':',';','}'):
            if self.cur().text=='<':
                children.append(self.parse_angle_group()); continue
            if self.cur().text=='(' and self.doc.lang=='Python':
                children.append(self.parse_group('(',')',coarse='parenthesized')); continue
            # extends etc are keywords/id pairs as expression may stop. Use phrase items one by one
            before=self.i
            children.append(self.parse_expression())
            if self.i==before: break
            if self.cur() and self.cur().text==',':
                children.append(leaf(self.doc,self.advance())); continue
        body=self.parse_body_after_header(children[-1] if children else None, class_context=True)
        if body is not None:
            if isinstance(body,list): children.extend(body)
            else: children.append(body)
        return node_from_children(self.doc,'class_definition',children,attrs={'keyword':kw_tok.text})
    def parse_angle_group(self):
        # generic <...> balanced
        children=[]; depth=0
        while self.cur():
            t=self.advance(); children.append(leaf(self.doc,t))
            if t.text=='<': depth+=1
            elif t.text=='>':
                depth-=1
                if depth<=0: break
            elif t.text in ('(',')'):
                pass
        return node_from_children(self.doc,'type_parameters',children)
    def parse_control(self):
        kw_tok=self.cur(); txt=kw_tok.text
        children=[leaf(self.doc,self.advance())]
        coarse={'if':'if','elif':'if','while':'while','for':'for','switch':'switch','match':'switch','try':'try'}.get(txt, txt+'_statement')
        # else / finally have no header (else if chained handled as body statement)
        if txt in ('else','finally','try','do'):
            body=self.parse_body_after_header(children[-1])
            if body is not None:
                if isinstance(body,list): children.extend(body)
                else: children.append(body)
            if txt=='do' and self.cur() and self.cur().text=='while':
                children.append(leaf(self.doc,self.advance()))
                if self.cur(): children.append(self.parse_expression())
            # else if: if body absent and cur is if, parse if as statement body
            if txt=='else' and self.cur() and self.cur().text=='if':
                children.append(self.parse_statement())
            if txt=='else':
                # else as standalone in phrase sequence belongs to preceding if - parser control of if handles else; this case is defensive
                return node_from_children(self.doc,'else_clause',children)
            return node_from_children(self.doc,coarse,children)
        # header: parenthesized or expression phrase
        if self.cur() and self.cur().text=='(':
            hdr=self.parse_group('(',')',coarse='parenthesized'); 
            # within for header, parenthesized group parsing may break at semicolons - parse_group handles semi as items
            children.append(hdr)
        else:
            # parse expression items until body separator colon/brace/newline topic; colon excluded
            saved=self.allow_colon; self.allow_colon=False
            # for python for loop `for x in y:` expression with `in` binary works
            items=[]
            while self.cur() and self.cur().text not in (':','{',';','}'):
                prev_line=self.doc.line_col(children[-1].end-1 if children[-1].end>children[-1].start else children[-1].start)[0] if children else self.cur().line
                if items and self.cur().line>prev_line and self.doc.lang!='Python':
                    break
                before=self.i
                items.append(self.parse_expression())
                if self.i==before: break
                if self.cur() and self.cur().text==',':
                    items.append(leaf(self.doc,self.advance())); continue
                # juxtaposed items could be declarations in C for etc; if next starts expr same line continue
                if self.cur() and self.cur().line==prev_line and self.cur().type in ('ident','meta') and self.cur().text not in ('{',':'):
                    continue
                break
            self.allow_colon=saved
            children.extend(items)
        body=self.parse_body_after_header(children[-1] if children else None)
        if body is not None:
            if isinstance(body,list): children.extend(body)
            else: children.append(body)
        # else chains for if
        if txt=='if':
            # skip same? else may be on next line
            if self.cur() and self.cur().text=='else':
                else_children=[leaf(self.doc,self.advance())]
                if self.cur() and self.cur().text in ('if','elif'):
                    else_children.append(self.parse_statement())
                else:
                    b=self.parse_body_after_header(else_children[-1])
                    if b is not None:
                        if isinstance(b,list): else_children.extend(b)
                        else: else_children.append(b)
                children.append(node_from_children(self.doc,'else_clause',else_children))
            elif self.cur() and self.cur().text=='elif':
                children.append(self.parse_statement())
        if txt=='try':
            while self.cur() and self.cur().text in ('catch','except','finally'):
                # parse catch as control, append
                children.append(self.parse_statement())
        return node_from_children(self.doc,coarse,children)
    def parse_body_after_header(self, last_node, class_context=False):
        t=self.cur()
        if t is None: return None
        if t.text=='{':
            return self.parse_brace_group(block_context='class' if class_context else 'function')
        if t.text==':':
            colon=leaf(self.doc,self.advance())
            # suite
            suite=self.parse_suite(colon)
            if suite is None: return [colon]
            return [colon, suite]
        if t.text=='=' and self.doc.lang in ('Scala','Kotlin'):
            eq=leaf(self.doc,self.advance()); expr=self.parse_expression(); return [eq,expr]
        if t.text in (';','}'):
            return None
