                else:
                    self.has_error=True; left=node_from_children(self.doc,'ternary',[left,q,cons]); continue
            # colon pair
            if t.text==':' and self.allow_colon and min_prec<=2:
                colon=leaf(self.doc,self.advance()); right=self.parse_expression(2)
                left=node_from_children(self.doc,'pair',[left,colon,right]); left.children[0].field='key'; left.children[2].field='value'; continue
            op_text=t.text
            # word operators are ident tokens
            prec=self.BINOP_PREC.get(op_text)
            if prec is None or prec<min_prec: break
            # sanity: operator token types op or word operator idents
            if t.type not in ('op','ident'): break
            # avoid consuming 'in'/'of' as binary in for phrase? It's fine.
            op=leaf(self.doc,self.advance())
            if op_text=='=>':
                if self.cur() and self.cur().text=='{':
                    right=self.parse_brace_group(block_context='function')
                else:
                    right=self.parse_expression(2)
                left=node_from_children(self.doc,'arrow_function',[left,op,right]); left.children[0].field='parameter'; left.children[2].field='body'; continue
            # right operand missing?
            if self.cur() is None or self.cur().text in (';',',',')',']','}'):
                self.has_error=True
                left=node_from_children(self.doc,'binary',[left,op],attrs={'op':op_text}); break
            next_min=prec if op_text in self.ASSIGN_OPS or op_text in ('**','=>') else prec+1
            right=self.parse_expression(next_min)
            if right is None:
                self.has_error=True; left=node_from_children(self.doc,'binary',[left,op],attrs={'op':op_text}); break
            if op_text in self.ASSIGN_OPS:
                left=node_from_children(self.doc,'assignment',[left,op,right],attrs={'op':op_text})
            else:
                left=node_from_children(self.doc,'binary',[left,op,right],attrs={'op':op_text})
            left.children[0].field='left'; left.children[1].field='operator'; left.children[2].field='right'
        return left
    def parse_unary(self):
        t=self.cur()
        if t is None: return None
        if t.text in ('!','-','+','~','++','--','...') or t.text in ('not','await','yield','delete','typeof','void'):
            op=leaf(self.doc,self.advance()); operand=self.parse_unary()
            if operand is None: self.has_error=True; return node_from_children(self.doc,'unary',[op])
            return node_from_children(self.doc,'unary',[op,operand],attrs={'op':t.text})
        if t.text=='new':
            op=leaf(self.doc,self.advance()); operand=self.parse_unary(); return node_from_children(self.doc,'new',[op,operand])
        if t.text in ('&','*') and self.doc.lang in ('C','Cpp','Rust','Go'):
            # could be pointer deref/reference in expression position
            op=leaf(self.doc,self.advance()); operand=self.parse_unary(); return node_from_children(self.doc,'unary',[op,operand],attrs={'op':t.text})
        return self.parse_postfix(self.parse_primary())
    def parse_postfix(self,left):
        if left is None: return None
        while True:
            t=self.cur()
            if t is None: break
            if t.text=='(':
                args=self.parse_group('(',')',coarse='arguments'); args.field='arguments'
                left=node_from_children(self.doc,'call',[left,args]); left.children[0].field='function'; continue
            if t.text=='[':
                open_t=leaf(self.doc,self.advance()); children=[left,open_t]
                children.extend(self.parse_comma_items_until(']'))
                if self.cur() and self.cur().text==']': children.append(leaf(self.doc,self.advance()))
                else: self.has_error=True
                left=node_from_children(self.doc,'subscript',children); continue
            if t.text in ('.','?.','::','->'):
                op=leaf(self.doc,self.advance())
                # property or number/index/meta
                if self.cur() and self.cur().type in ('ident','meta','number'):
                    prop=leaf(self.doc,self.advance(),role='property'); prop.field='property'
                    left=node_from_children(self.doc,'member',[left,op,prop],attrs={'op':t.text}); left.children[0].field='object'; continue
                elif self.cur() and self.cur().text=='(':
                    # .()
                    args=self.parse_group('(',')',coarse='arguments'); left=node_from_children(self.doc,'member',[left,op,args]); continue
                else:
                    self.has_error=True; left=node_from_children(self.doc,'member',[left,op]); continue
            if t.type=='template':
                templ=self.parse_template_string(); left=node_from_children(self.doc,'call',[left,templ]); continue
            if t.text in ('++','--'):
                op=leaf(self.doc,self.advance()); left=node_from_children(self.doc,'update',[left,op]); continue
            if t.text=='{' and self.doc.lang in ('Go','Rust','C','Cpp','CSharp','Dart','Kotlin','Scala') and left.coarse=='leaf':
                # composite/struct literal
                brace=self.parse_brace_group(block_context='object'); left=node_from_children(self.doc,'object',[left,brace]); continue
            break
        return left
    def parse_primary(self):
        t=self.cur()
        if t is None: return None
        if t.type=='comment':
            return leaf(self.doc,self.advance())
        if t.type=='meta':
            return leaf(self.doc,self.advance())
        if t.type=='string':
            return self.make_string_node(self.advance())
        if t.type=='template':
            return self.parse_template_string()
        if t.type in ('number','text'):
            return leaf(self.doc,self.advance())
        if t.text=='(':
            # lambda parameters possibility handled in expression arrow: parenthesized node kept, arrow code makes param field.
            return self.parse_group('(',')',coarse='parenthesized')
        if t.text=='[':
            open_t=leaf(self.doc,self.advance()); children=[open_t]
            children.extend(self.parse_comma_items_until(']'))
            if self.cur() and self.cur().text==']': children.append(leaf(self.doc,self.advance()))
            else: self.has_error=True
            return node_from_children(self.doc,'array',children)
        if t.text=='{':
            return self.parse_brace_group(block_context='object')
        if t.text=='<':
            node=self.try_parse_jsx()
            if node is not None: return node
            # as a leaf operator if standalone
            return leaf(self.doc,self.advance())
        if t.type=='ident':
            txt=t.text
            if txt=='function':
                return self.parse_function_def()
            if txt=='class':
                return self.parse_class_def()
            if txt=='lambda':
                kw=leaf(self.doc,self.advance()); children=[kw]
                saved=self.allow_colon; self.allow_colon=False
                # params: comma items until :
                while self.cur() and self.cur().text!=':':
                    children.append(self.parse_expression())
                    if self.cur() and self.cur().text==',': children.append(leaf(self.doc,self.advance())); continue
                    break
                self.allow_colon=saved
                if self.cur() and self.cur().text==':': children.append(leaf(self.doc,self.advance())); children.append(self.parse_expression())
                return node_from_children(self.doc,'lambda',children)
            if txt in ('if','while','for') and self.doc.lang in ('Rust','Kotlin','Scala'):
                return self.parse_statement()
            return leaf(self.doc,self.advance())
        # operators as leaf in primary context ( e.g., '*' in import *, '&' etc.)
        # To avoid loops, consume it
        return leaf(self.doc,self.advance())
    def make_string_node(self,tok):
        # children: opening quote(s), content fragment, closing quote(s)
        children=[]
        quote=tok.quote or '"'
        # triple?
        text=tok.text
        oplen=3 if text.startswith(quote*3) else 1
        open_end=tok.start+oplen
        children.append(Node(self.doc,'leaf',tok.start,open_end,[],named=False,token_type='op',token_text=self.doc.text[tok.start:open_end]))
        if tok.content_start is not None and tok.content_end is not None and tok.content_end>tok.content_start:
            content_text=self.doc.text[tok.content_start:tok.content_end]
            children.append(Node(self.doc,'leaf',tok.content_start,tok.content_end,[],named=True,token_type='string_content',token_text=content_text))
        close_start=tok.content_end if tok.content_end is not None else tok.end
        if close_start<tok.end:
            children.append(Node(self.doc,'leaf',close_start,tok.end,[],named=False,token_type='op',token_text=self.doc.text[close_start:tok.end]))
        n=node_from_children(self.doc,'string',children)
        if children: n.start=tok.start; n.end=tok.end
        return n
    def parse_template_string(self):
        start_tok=self.advance(); children=[leaf(self.doc,start_tok)]
        while self.cur():
            t=self.cur()
            if t.type=='template':
                children.append(leaf(self.doc,self.advance())); break
            if t.type=='string_content':
                children.append(leaf(self.doc,self.advance())); continue
            if t.text=='${':
                open_t=leaf(self.doc,self.advance()); sub=[open_t]
                expr=self.parse_expression(); 
                if expr: sub.append(expr)
                if self.cur() and self.cur().text=='}': sub.append(leaf(self.doc,self.advance()))
                children.append(node_from_children(self.doc,'template_substitution',sub)); continue
            # unexpected
            children.append(leaf(self.doc,self.advance()))
        return node_from_children(self.doc,'template_string',children)
    def parse_group(self,open_text,close_text,coarse='parenthesized'):
        children=[]
        if self.cur() and self.cur().text==open_text: children.append(leaf(self.doc,self.advance()))
        else: self.has_error=True; return node_from_children(self.doc,coarse,children)
        items=self.parse_comma_items_until(close_text)
        children.extend(items)
        if self.cur() and self.cur().text==close_text: children.append(leaf(self.doc,self.advance()))
        else: self.has_error=True
        if coarse=='parenthesized':
            # if more than one item/comma, tuple-like still parenthesized in many langs, keep parenthesized
            pass
        return node_from_children(self.doc,coarse,children)
    def parse_comma_items_until(self,close_text):
        children=[]
        while self.cur() and self.cur().text!=close_text:
            if self.cur().text==',':
                children.append(leaf(self.doc,self.advance())); continue
            if self.cur().text==';':
                children.append(leaf(self.doc,self.advance())); continue
            if self.cur().text in (')',']','}'):
                break
            before=self.i
            # group item can be a statement-ish in for headers etc; and declarations in params.
            # Use phrase items within group: parse one expression, then cluster juxtaposed before comma/close
            item=self.parse_group_item(close_text)
            if item is None or self.i==before:
                self.has_error=True
                if self.cur(): children.append(leaf(self.doc,self.advance()))
                continue
            children.append(item)
        return children
    def parse_group_item(self,close_text):
        # parse expression, and if following tokens before comma/close are juxtaposed atoms (typed param, annotation), cluster them
        expr=self.parse_expression()
        if expr is None: return None
        items=[expr]
        while self.cur() and self.cur().text not in (',',';',close_text,')',']','}'):
            # only juxtapose same line or type-ish
            if self.cur().type in ('ident','meta','number','string') or self.cur().text in ('(','[','<'):
                before=self.i
                it=self.parse_expression()
                if it is None or self.i==before: break
                items.append(it); continue
            break
        if len(items)==1: return expr
        return node_from_children(self.doc,'parameter',items)
    def parse_brace_group(self,block_context=None):
        children=[]
        if self.cur() and self.cur().text=='{': children.append(leaf(self.doc,self.advance()))
        else: self.has_error=True; return node_from_children(self.doc,'brace',children)
        seq=self.parse_sequence({'}'})
        children.extend(seq)
        end_tok=None
        if self.cur() and self.cur().text=='}': end_tok=leaf(self.doc,self.advance()); children.append(end_tok)
        else: self.has_error=True
        # braces may contain only commas in sequence -> parse_sequence already appended commas
        pair_like=any(c.coarse=='pair' for c in seq)
        attrs={'block_context':block_context,'pair_like':pair_like}
        coarse='object' if block_context=='object' and (pair_like or not seq) else 'block'
        if block_context=='object' and not pair_like:
            # Could be a set/dict without colons or JS object shorthand {a,b}. Keep object if expression context and no statement separators.
            # If seq has expression_statements/semicolon it's a block.
            if any(c.coarse=='expression_statement' for c in seq): coarse='block'
            else: coarse='object'
        return node_from_children(self.doc,coarse,children,attrs=attrs)
    def try_parse_jsx(self):
        # Only attempt if next is ident/meta and a closing '>' likely on same-ish region or language HTML/Tsx/JS
        if self.doc.lang not in ('Html','JavaScript','TypeScript','Tsx'):
            return None
        save=self.i
        # Parse opening
        lt=self.advance(); children_open=[leaf(self.doc,lt)]
        if self.cur() and self.cur().text=='/':
            self.i=save; return None
        if not (self.cur() and self.cur().type in ('ident','meta')):
            self.i=save; return None
        tag=leaf(self.doc,self.advance(),role='type'); children_open.append(tag)
        self_closing=False
        # attributes
        while self.cur() and self.cur().text not in ('>','/>'):
            if self.cur().text=='/' and self.peek(1) and self.peek(1).text=='>':
                children_open.append(leaf(self.doc,self.advance())); self_closing=True; break
            if self.cur().text=='{':
                children_open.append(self.parse_brace_group(block_context='object')); continue
            if self.cur().type in ('ident','meta'):
                # attribute: name (= value)?
                attr_children=[leaf(self.doc,self.advance())]
                if self.cur() and self.cur().text=='=':
                    attr_children.append(leaf(self.doc,self.advance()))
                    if self.cur(): 
                        if self.cur().text=='{': attr_children.append(self.parse_brace_group(block_context='object'))
                        else: attr_children.append(self.parse_primary())
                children_open.append(node_from_children(self.doc,'jsx_attribute',attr_children)); continue
            # hyphen in attr names tokenized as - etc consume sequence
            children_open.append(leaf(self.doc,self.advance()))
        if self.cur() and self.cur().text=='>': children_open.append(leaf(self.doc,self.advance()))
        elif self.cur() and self.cur().text=='/>': children_open.append(leaf(self.doc,self.advance())); self_closing=True
        else:
            # if no '>' soon, may be comparison; if we consumed many tokens uncertain, accept as jsx if HTML
            if self.doc.lang!='Html': self.i=save; return None
        if self_closing:
            return node_from_children(self.doc,'jsx_self_closing',children_open)
        opening=node_from_children(self.doc,'jsx_opening',children_open)
        children=[opening]
        # children content until </tag>
        while self.cur():
            if self.cur().text=='<' and self.peek(1) and self.peek(1).text=='/':
                close_children=[leaf(self.doc,self.advance()), leaf(self.doc,self.advance())]
                if self.cur() and self.cur().type in ('ident','meta'): close_children.append(leaf(self.doc,self.advance()))
                if self.cur() and self.cur().text=='>': close_children.append(leaf(self.doc,self.advance()))
                children.append(node_from_children(self.doc,'jsx_closing',close_children)); break
            if self.cur().text=='{':
                children.append(self.parse_brace_group(block_context='object')); continue
            if self.cur().text=='<':
                child=self.try_parse_jsx()
                if child: children.append(child); continue
                children.append(leaf(self.doc,self.advance())); continue
            if self.cur().type=='text':
                children.append(leaf(self.doc,self.advance())); continue
            # JSX text tokens: consume tokens until '<' or '{' and combine as a text-like cluster? If a meta, keep separate so it can capture.
            if self.cur().type=='meta':
                children.append(leaf(self.doc,self.advance())); continue
            # consume a run as one 'text' node spanning tokens
            start=self.cur().start; end=self.cur().end; toks=[]
            while self.cur() and self.cur().text not in ('<','{'):
                toks.append(self.advance()); end=toks[-1].end
            if toks:
                # if only one ident, as leaf text
                n=Node(self.doc,'leaf',start,end,[],named=True,token_type='text',token_text=self.doc.text[start:end])
                children.append(n)
            else:
                break
        return node_from_children(self.doc,'jsx_element',children)

def kw_line(doc,kw_node):
    return doc.line_col(kw_node.start)[0]

# Pattern extraction and matching
class PatternError(Exception):
    def __init__(self,cause):
        super().__init__(cause); self.cause=cause

def extract_pattern_root(doc):
    root=doc.parse()
    if not root.children:
        # no tokens
        if not doc.tokens:
            raise PatternError(f"No AST root is detected. Please check the pattern source `{doc.text}`.")
        # tokens but weird e.g. closing ) primary statement could create child; if no children fallback leaf
    # multiple check: named children? Tree-sitter root child count including comments?
    # Count children that are not? root children list includes statements / comments. If >1 and not (single statement plus comment on diff line?) -> multiple. Our parse_sequence attaches trailing comments, leading comments are children.
    if len(root.children)>1:
        raise PatternError(f"Multiple AST nodes are detected. Please check the pattern source `{doc.text}`.")
    if len(root.children)==0:
        raise PatternError(f"No AST root is detected. Please check the pattern source `{doc.text}`.")
    node=root
    # Descend single child chain
    while len(node.children)==1:
        child=node.children[0]
        # Don't descend into a string's sole content etc if node is string and child is a leaf op? String node has >1 if quotes; if malformed one child, descending to quote seems wrong but small.
        # Also if child is unnamed leaf and node is not root/empty_statement, maybe stop? Original ';' descends to ';' unnamed. Empty statement has one ';'.
        node=child
        if node.is_leaf(): break
    return node

def make_pattern(pattern_text, lang, selector=None, context_text=None):
    actual_text=context_text if context_text is not None else pattern_text
    doc=SourceDoc(actual_text, lang, is_pattern=True)
    # error pattern for unbalanced opener if positive depth at end and underlying parse has_error
    pat_root=None; error_node=None
    # selector validation prior? Original invalid kind error takes precedence over multiple? Test selector invalid with multiple pattern may... do selector kind validity after parse extraction? For run --selector invalid, cause was Kind invalid only.
    root_doc_node=doc.parse()
    if selector is not None:
        ks=KINDS.get(lang)
        if ks is not None and selector not in ks and selector not in (ROOT_KIND.get(lang),):
            # root kinds might not be in node enum? program is in JS enum? Check JS kinds list doesn't include program maybe (114 list starts arguments... program not listed!) Selector program accepted earlier. So allow root kind and ERROR.
            if selector not in ('ERROR',):
                raise PatternError(f"Kind `{selector}` is invalid.")
        # find first node preorder in root trees (including root)
        found=None
        for n in all_nodes(root_doc_node):
            if n.ext_kind==selector:
                found=n; break
        if found is None:
            raise PatternError(f"Fails to create Contextual pattern: selector `{selector}` matches no node in the context `{actual_text}`.")
        pat_root=found
    else:
        # empty check
        if not doc.tokens:
            raise PatternError(f"No AST root is detected. Please check the pattern source `{actual_text}`.")
        # unbalanced error: if parser has_error and bracket balance positive or trailing op, use error node for matching and debug.
        # extract normally but if has_error wrap?
        try:
            pat_root=extract_pattern_root(doc)
        except PatternError:
            raise
        if doc.has_error:
            # Create error node flattening extracted root leaves in order, if the extracted root itself isn't a single token.
            # But pattern class { etc possibly has_error due missing close; original not error sometimes. We'll only do error if tokens end with an operator or an opening bracket token is last significant or bracket depth >0 with a '('
            toks=doc.tokens
            depth=0; has_open=False
            for t in toks:
                if t.text in ('(','[','{'): depth+=1; has_open=True
                elif t.text in (')',']','}'): depth-=1
            ends_op=toks and toks[-1].text in ('+','-','*','/','%','.','=>','?','&&','||','==','=','<','>','(')
            if ends_op or (depth>0 and toks and toks[-1].text=='('):
                leaves=[]
                for t in toks:
                    # only tokens within original pattern; meta leaves prepared
                    leaves.append(leaf(doc,t))
                error_node=node_from_children(doc,'error',leaves)
                pat_root=error_node
    # determine has_error flag on doc for warning logic: bracket imbalance/trailing op/parser error
    pat_root._doc=doc if hasattr(pat_root,'_doc') else None
    return pat_root, doc

class MatchEnv:
    def __init__(self):
        self.single={}
        self.multi={}
        self.transformed={}
    def copy(self):
        e=MatchEnv(); e.single=dict(self.single); e.multi={k:list(v) for k,v in self.multi.items()}; e.transformed=dict(self.transformed); return e
    def assign_from(self,other):
        self.single=dict(other.single); self.multi={k:list(v) for k,v in other.multi.items()}; self.transformed=dict(other.transformed)

def nodes_equiv(n1,n2):
    return n1.leaf_texts()==n2.leaf_texts()

def visible_children(node, strictness):
    if strictness in ('cst','smart',None):
        return list(node.children)
    if strictness=='ast':
        return [c for c in node.children if c.named]
    if strictness in ('relaxed','signature'):
        return [c for c in node.children if c.named and c.ext_kind!='comment']
    if strictness=='template':
        return list(node.children)
    return list(node.children)

def match_node(pattern, target, env, strictness='smart'):
    # meta special handled mainly in sequence, but root/direct calls
    if pattern.meta:
        if pattern.meta.get('multi'):
            # As a direct node, treat as single capture (root case)
            return _capture_single(pattern.meta, target, env)
        else:
            return _capture_single(pattern.meta, target, env)
    if pattern.coarse=='error':
        # prefix sequence match
        penv=env.copy()
        if match_children_prefix(pattern.children, target.children, penv, strictness):
            env.assign_from(penv); return True
        return False
    # string content meta capture
    if pattern.coarse=='string' and target.coarse=='string':
        # check quote style textual? First/last leaves text must match in default, content could be meta whole
        p_contents=[c for c in pattern.children if c.token_type=='string_content']
        t_contents=[c for c in target.children if c.token_type=='string_content']
        if len(p_contents)==1:
            pm=parse_meta_text(p_contents[0].text())
            if pm and not pm.get('multi'):
                # quotes must match? original "$A" matches 'hello' and "hello"? It matched both? Earlier "$A" pattern against "hello" only. Let's keep quote type must match opening token text (single vs double) because string nodes children quotes differ and original cst/smart would fail if quote different.
                if pattern.children and target.children and pattern.children[0].text()!=target.children[0].text():
                    # JS string with ' vs " are different unnamed nodes, smart respects.
                    return False
                if not t_contents:
                    # empty string capture? create zero-width pseudo? Original content node absent if empty; meta matching "" maybe captures empty? skip fail for now
                    return False
                return _capture_single(pm, t_contents[0], env)
        # fall through standard
    if pattern.is_leaf() or target.is_leaf():
        if not (pattern.is_leaf() and target.is_leaf()): return False
        if strictness=='signature':
            return pattern.token_type==target.token_type and (pattern.named==target.named) and _leaf_coarse_sig(pattern)==_leaf_coarse_sig(target)
        if strictness=='template':
            return pattern.text()==target.text()
        # For ast mode, internal nodes filtered, leaves named compare text; unnamed leaves won't be called except direct root patterns e.g. '('.
        return pattern.text()==target.text()
    # internal kind comparison
    if strictness!='template':
        # compare coarse, with some equivalences
        if not _coarse_compatible(pattern,target):
            return False
    p_children=visible_children(pattern, strictness)
    t_children=visible_children(target, strictness)
    penv=env.copy()
    if match_children(p_children, t_children, penv, strictness):
        env.assign_from(penv); return True
    return False

def _leaf_coarse_sig(node):
    if node.token_type=='ident': return 'identifier'
    return node.token_type
def _coarse_compatible(p,t):
    if p.coarse==t.coarse: return True
    # object vs brace/block are same braces family
    if p.coarse in ('object','brace','block') and t.coarse in ('object','brace','block'): return True
    if p.coarse in ('tuple','parenthesized') and t.coarse in ('tuple','parenthesized'): return True
    if p.coarse in ('cluster','declaration','variable_declaration') and t.coarse in ('cluster','declaration','variable_declaration'): return True
    # statement keywords nodes coarse named like break_statement etc stored as coarse string directly
    if p.ext_kind==t.ext_kind: return True
    return False

def _capture_single(meta, target, env):
    if meta.get('anonymous') or not meta.get('name'):
        return True
    name=meta['name']
    if name in env.single:
        return nodes_equiv(env.single[name], target)
    env2=target  # mutation direct okay because callers often copy at node level but sequence also works with copies
