    if meta.get('anonymous') or not meta.get('name'):
        return True
    name=meta['name']
    if name in env.multi:
        existing=env.multi[name]
        if len(existing)!=len(targets): return False
        return all(nodes_equiv(a,b) for a,b in zip(existing,targets))
    env.multi[name]=list(targets)
