def match_children(p_children, t_children, env, strictness):
    return _match_seq(p_children,0,t_children,0,env,strictness,allow_prefix=False)
def match_children_prefix(p_children,t_children,env,strictness):
    return _match_seq(p_children,0,t_children,0,env,strictness,allow_prefix=True)

def _match_seq(p,pi,t,ti,env,strictness,allow_prefix=False):
    # recursive backtracking; env mutated only on success path via copy at branch attempts
    if pi>=len(p):
        return allow_prefix or ti>=len(t) or _all_skippable_target(t[ti:], strictness, at_end=True)
    pat=p[pi]
    # multi meta
    if pat.meta and pat.meta.get('multi'):
        # try consume k from 0.. remaining (prefer greedy? Original typical expanding to allow rest: greedy from high to low may capture correct. But for $A,$$$ following specifics, backtracking handles. Prefer greedy largest first often aligns with $$$ alone.)
        for k in range(len(t)-ti, -1, -1):
            env2=env.copy()
            if not _capture_multi(pat.meta, t[ti:ti+k], env2): continue
            if _match_seq(p,pi+1,t,ti+k,env2,strictness,allow_prefix):
                env.assign_from(env2); return True
        return False
    # skipping target trivia under some modes
    if ti<len(t) and _can_skip_target(t[ti], strictness, p, pi):
        env2=env.copy()
        if _match_seq(p,pi,t,ti+1,env2,strictness,allow_prefix):
            env.assign_from(env2); return True
        # fall through try match current
    if ti>=len(t):
        return False
    # Single meta: consume one target child. In ast/relaxed/signature modes children only named. In smart/cst it could consume an unnamed child if structurally aligned (rare).
    if pat.meta:
        env2=env.copy()
        if _capture_single(pat.meta, t[ti], env2) and _match_seq(p,pi+1,t,ti+1,env2,strictness,allow_prefix):
            env.assign_from(env2); return True
        return False
    # normal node
    env2=env.copy()
    if match_node(pat, t[ti], env2, strictness) and _match_seq(p,pi+1,t,ti+1,env2,strictness,allow_prefix):
        env.assign_from(env2); return True
    return False

