        if node.is_leaf() and not node.named and node.text() in (',',):
            # Only skip if pattern current is not comma
            if p_children is not None and pi is not None and pi<len(p_children) and p_children[pi].is_leaf() and p_children[pi].text()==',':
                return False
            return True
    return False
def _all_skippable_target(nodes, strictness, at_end=False):
    if not nodes: return True
    if strictness in (None,'smart','template'):
        return all(n.is_leaf() and not n.named and n.text()==',' for n in nodes)
    return False

def find_matches(pat_root, target_doc, strictness='smart'):
    root=target_doc.parse()
    out=[]
    # candidate traversal
    for node in all_nodes(root):
        # pattern root unnamed leaf can match unnamed nodes; named/meta determines
        if pat_root.meta and pat_root.meta.get('multi'):
            pass # all nodes allowed
        elif pat_root.meta:
            if not node.named: continue
        elif pat_root.is_leaf() and not pat_root.named:
            pass
        else:
            if not node.named: continue
        env=MatchEnv()
        if match_node(pat_root, node, env, strictness):
            out.append((node,env))
    return out

