def meta_text_for_single(env,name, doc=None):
    if name in env.transformed: return env.transformed[name]
    node=env.single.get(name)
    if node is None: return ''
    return dedent_capture(node.text(), node)
def meta_text_for_multi(env,name):
    nodes=env.multi.get(name)
    if not nodes: return ''
    first=nodes[0]; last=nodes[-1]
    text=first.doc.text[first.start:last.end]
    return dedent_capture(text, first)
def dedent_capture(text, node):
    if '\n' not in text: return text
    # indent string = whitespace from start of line to node start if only spaces/tabs before it? Or line indent.
    doc=node.doc; line_start=doc.text.rfind('\n',0,node.start)+1
    prefix=doc.text[line_start:node.start]
    indent=''
    if prefix.strip()=='':
        indent=prefix
    else:
        # line leading whitespace
        m=re.match(r'[ \t]*', doc.text[line_start:]); indent=m.group(0) if m else ''
    if not indent: return text
    lines=text.split('\n')
    for i in range(1,len(lines)):
        if lines[i].startswith(indent): lines[i]=lines[i][len(indent):]
        else:
            # remove up to len indent spaces if line has spaces
            stripped=lines[i].lstrip(' ')
            cnt=len(lines[i])-len(stripped)
            lines[i]=' '*(cnt-len(indent))+stripped if cnt>len(indent) else stripped
    return '\n'.join(lines)

_REWRITE_NAME_RE=re.compile(r'([A-Z0-9_]+)')
def substitute_template(template, env, match_node=None, apply_indent=False):
    if template is None: return None
    out=[]; i=0; s=template
    while i<len(s):
        if s[i]=='$':
            # count dollars, but if >3, emit one and continue (matches $$$$B -> $ + $$$B)
            j=i
            while j<len(s) and s[j]=='$': j+=1
            d=j-i
            if d>3:
                out.append('$'); i+=1; continue
            m=_REWRITE_NAME_RE.match(s,j)
            if not m:
                out.append(s[i:j]); i=j; continue
            name=m.group(1); end=m.end()
            # name should start with uppercase/digit/underscore – regex ensures; but if name starts with digit, original replaced $5 with empty (it did) so accept
            if d==3:
                out.append(meta_text_for_multi(env,name))
            else:
                # transformed or single; if name exists only multi -> empty
                out.append(meta_text_for_single(env,name))
            i=end; continue
        out.append(s[i]); i+=1
    result=''.join(out)
    if apply_indent and match_node is not None:
        doc=match_node.doc; line_start=doc.text.rfind('\n',0,match_node.start)+1
        m=re.match(r'[ ]*', doc.text[line_start:])
        indent=m.group(0) if m else ''
        if indent and '\n' in result:
            lines=result.split('\n')
            result='\n'.join([lines[0]]+[indent+ln for ln in lines[1:]])
    return result

