            if d=='lang' and 'debug_query' in dests:
                dests.insert(dests.index('debug_query'),d)
            elif d=='json' and 'include_metadata' in dests:
                dests.insert(dests.index('include_metadata'),d)
            else:
                dests.append(d)
    if not dests:
        return spec.canonical_usage()
    parts=[]
    base=f"{BIN} {spec.path}".strip() if spec.path else BIN
    parts.append(base)
