import os, re, sys
from yamlmini import parse_yaml, YamlError
from languages import canonical_lang, EXT_TO_LANG

class AppError(Exception):
    def __init__(self, code, text):
        super().__init__(text); self.code=code; self.text=text

def format_app_error(title, help_text=None, see=None, causes=None):
    s=f"Error: {title}\n"
    if help_text: s+=f"Help: {help_text}\n"
    if see: s+=f"See also: {see}\n"
    if causes:
        s+="\n✖ Caused by\n"
        for c in causes:
            # causes may contain newlines; first line gets marker, rest as-is (regex errors)
            parts=str(c).split('\n')
            s+=f"╰▻ {parts[0]}\n"
            for p in parts[1:]: s+=p+"\n"
    s+="\n"
    return s

def os_error_str(e):
    import errno
    return f"{e.strerror or str(e)} (os error {e.errno})" if getattr(e,'errno',None) else str(e)

class Project:
    def __init__(self, config_path=None, project_dir=None, config=None, is_project=False):
        self.config_path=config_path; self.project_dir=project_dir; self.config=config or {}; self.is_project=is_project
        self.custom_langs={}
        if isinstance(self.config,dict):
            cl=self.config.get('customLanguages') or {}
            if isinstance(cl,dict): self.custom_langs=cl
    def rule_dirs(self):
        v=self.config.get('ruleDirs') if isinstance(self.config,dict) else None
        return list(v) if isinstance(v,list) else []
    def util_dirs(self):
        v=self.config.get('utilDirs') if isinstance(self.config,dict) else None
        return list(v) if isinstance(v,list) else []
    def test_configs(self):
        v=self.config.get('testConfigs') if isinstance(self.config,dict) else None
        return list(v) if isinstance(v,list) else []
    def language_globs(self):
        v=self.config.get('languageGlobs') if isinstance(self.config,dict) else None
        out={}
        if isinstance(v,dict):
            for k,vals in v.items():
                canon=canonical_lang(k) or _custom_canon(self,k) or str(k)
                if isinstance(vals,list): out[canon]=[str(x) for x in vals]
                elif vals is not None: out[canon]=[str(vals)]
        # custom languages extensions also as globs
        for name,cfg in self.custom_langs.items():
            if isinstance(cfg,dict) and isinstance(cfg.get('extensions'),list):
                out.setdefault(str(name),[]).extend([f"*.{e}" for e in cfg['extensions']])
        return out

def _custom_canon(project,name):
    if project and isinstance(project.custom_langs,dict):
        for k in project.custom_langs:
            if k.lower()==str(name).lower(): return k
    return None

def parse_config_text(text, path_for_errors):
    try:
        data=parse_yaml(text)
    except Exception as e:
        msg=getattr(e,'message',str(e))
        raise AppError(8, format_app_error("Cannot parse configuration","The sgconfig.yml is not a valid configuration file. Please refer to doc and fix the error.","https://ast-grep.github.io/reference/sgconfig.html",[msg]))
    if data is None: data={}
    if not isinstance(data,dict):
        raise AppError(8, format_app_error("Cannot parse configuration","The sgconfig.yml is not a valid configuration file. Please refer to doc and fix the error.","https://ast-grep.github.io/reference/sgconfig.html",["invalid type: sequence, expected struct ProjectConfig" if isinstance(data,list) else f"invalid type: {type(data).__name__}, expected struct ProjectConfig"]))
    # basic type validations resembling serde for known fields
    for field in ('ruleDirs','utilDirs','testConfigs'):
        if field in data and data[field] is not None and not isinstance(data[field],list):
            val=data[field]; typ='string' if isinstance(val,str) else type(val).__name__
            rendered=f'"{val}"' if isinstance(val,str) else str(val)
            # find line/col of value
            line,col=_find_yaml_value_pos(text,field)
            cause=f"{field}: invalid type: {typ} {rendered}, expected a sequence at line {line} column {col}"
            raise AppError(8, format_app_error("Cannot parse configuration","The sgconfig.yml is not a valid configuration file. Please refer to doc and fix the error.","https://ast-grep.github.io/reference/sgconfig.html",[cause]))
    return data

def _find_yaml_value_pos(text, field):
    for idx,line in enumerate(text.splitlines(),1):
        m=re.match(rf'\s*{re.escape(field)}\s*:\s*',line)
        if m: return idx, m.end()+1
    return 1,1

def find_project(config_arg=None, required=False):
    cwd=os.getcwd()
    if config_arg:
        path=config_arg
        try:
            with open(path,'r',encoding='utf-8') as f: text=f.read()
        except OSError as e:
            raise AppError(6, format_app_error("Cannot read configuration.","Please add an sgconfig.yml configuration file in the project root to run the scan command.","https://ast-grep.github.io/guide/rule-config.html",[os_error_str(e)]))
        cfg=parse_config_text(text,path)
        apath=os.path.abspath(path)
        return Project(apath, os.path.dirname(apath), cfg, True)
    cur=cwd
    while True:
        cand=os.path.join(cur,'sgconfig.yml')
        if os.path.isfile(cand):
            try:
                with open(cand,'r',encoding='utf-8') as f: text=f.read()
            except OSError as e:
                raise AppError(6, format_app_error("Cannot read configuration.","Please add an sgconfig.yml configuration file in the project root to run the scan command.","https://ast-grep.github.io/guide/rule-config.html",[os_error_str(e)]))
            cfg=parse_config_text(text,cand)
            return Project(os.path.abspath(cand), os.path.abspath(cur), cfg, True)
        parent=os.path.dirname(cur)
        if parent==cur: break
        cur=parent
    if required:
        raise AppError(3, format_app_error("No ast-grep project configuration is found.","You need to create an ast-grep project for this command. Try `sg new` to create one.","https://ast-grep.github.io/guide/scan-project.html"))
    return Project(None,None,{},False)

# -------- glob matching ----------
def glob_to_regex(pat):
    # gitignore-ish conversion for CLI/rule globs where pattern is matched whole string
    i=0; res=''
    while i<len(pat):
        c=pat[i]
        if c=='*':
            if pat.startswith('**/',i):
                res+='(?:.*/)?'; i+=3
            elif pat.startswith('**',i):
                res+='.*'; i+=2
            else:
                res+='[^/]*'; i+=1
        elif c=='?':
            res+='[^/]'; i+=1
        elif c=='[':
            j=i+1
            if j<len(pat) and pat[j]=='!': j+=1
            if j<len(pat) and pat[j]==']': j+=1
            while j<len(pat) and pat[j]!=']': j+=1
            if j>=len(pat): raise ValueError(f"error parsing glob '{pat}': unclosed character class; missing ']'")
            stuff=pat[i+1:j]
            if stuff.startswith('!'): stuff='^'+stuff[1:]
            res+='['+stuff+']'; i=j+1
        elif c=='{':
            j=pat.find('}',i+1)
            if j<0: raise ValueError(f"error parsing glob '{pat}': unclosed alternate group; missing '}}'")
            inner=pat[i+1:j]
            parts=inner.split(',')
            res+='(?:'+'|'.join(re.escape(p) for p in parts)+')'; i=j+1
        else:
            res+=re.escape(c); i+=1
    return re.compile('^'+res+'$')
def validate_globs(globs):
    for g in globs or []:
        pat=g[1:] if g.startswith('!') else g
        try: glob_to_regex(pat)
        except ValueError as e:
            raise AppError(9, format_app_error("Cannot build glob from CLI flag","The patterns in --globs is invalid. Please refer to doc and fix the error.","https://ast-grep.github.io/reference/cli.html",[str(e)]))
def glob_match(pat, path, case_insensitive=False):
    # Path uses posix separators
    p=path.replace(os.sep,'/')
    orig=pat
    if case_insensitive: pat=pat.lower(); p=p.lower()
    try:
        if pat.endswith('/'):
            regex=glob_to_regex(pat.rstrip('/'))
            # match dir itself or any parent dir of path
            parts=p.split('/')
            for k in range(1,len(parts)):
                if regex.match('/'.join(parts[:k])): return True
            return bool(regex.match(p.rstrip('/')))
        # patterns without slash in CLI-override mode match basename anywhere; this function has a flag via caller choices (we use gitignore style here)
        return bool(glob_to_regex(pat).match(p))
    except Exception:
        return False

def gitignore_match(pat, rel_path, is_dir=False):
    # pat already stripped neg sign, rel_path relative to pattern base, posix
    pat=pat.strip()
    if not pat or pat.startswith('#'): return False
    dir_only=pat.endswith('/')
    if dir_only and not is_dir:
        # a file under a matched dir is ignored: caller checks dirs separately; for file, check parents
        parts=rel_path.split('/')
        for k in range(1,len(parts)):
            if gitignore_match(pat, '/'.join(parts[:k]), True): return True
        return False
    anchored=False
    if pat.startswith('/'):
        anchored=True; pat=pat[1:]
    if '/' not in pat.rstrip('/'):
        # match basename
        return glob_match(pat.rstrip('/'), rel_path.split('/')[-1])
    if not anchored and not pat.startswith('**/'):
        # pattern with slash not leading: in gitignore it's relative to base (anchored effectively at base) if contains slash in middle.
        return glob_match(pat.rstrip('/'), rel_path)
    return glob_match(pat.rstrip('/'), rel_path)

def normalize_display(path):
    if not path: return path
    is_abs=path.startswith('/'); parts=[]
    for part in path.split('/'):
        if part=='': 
            continue
        if part=='.': continue
        parts.append(part)
    out='/'.join(parts)
    if is_abs: out='/'+out
    return out or ('/' if is_abs else '.')

class FileEntry:
    __slots__=("display","fs_path","lang","root_display")
    def __init__(self,display,fs_path,lang,root_display=None): self.display=display; self.fs_path=fs_path; self.lang=lang; self.root_display=root_display

def lang_for_file(fs_path, display, project):
    # languageGlobs first
    globs=project.language_globs() if project else {}
    cand_paths=[]
    cand_paths.append(display)
    cand_paths.append(os.path.basename(fs_path))
    if project and project.project_dir:
        try: cand_paths.append(os.path.relpath(os.path.abspath(fs_path), project.project_dir))
        except: pass
    for lang, patterns in globs.items():
        for pat in patterns:
            for cp in cand_paths:
                # language globs seem basename / path patterns; try both whole and basename-style
                if glob_match(pat,cp) or glob_match(pat, os.path.basename(cp)):
                    return lang
    base=os.path.basename(fs_path)
    if '.' in base:
        ext=base.rsplit('.',1)[1]
        lang=EXT_TO_LANG.get(ext)
        if lang: return lang
    return None

def _has_git_ancestor(path):
    cur=os.path.abspath(path)
    while True:
        if os.path.exists(os.path.join(cur,'.git')): return True
        parent=os.path.dirname(cur)
        if parent==cur: return False
        cur=parent

def _load_ignore_patterns(dir_path, no_ignore_set):
    patterns=[]  # (pattern_text, negated, base_abs)
    files=[]
    if 'dot' not in no_ignore_set:
        files.append(os.path.join(dir_path,'.ignore'))
    if 'vcs' not in no_ignore_set and os.path.exists(os.path.join(dir_path,'.git')):
        files.append(os.path.join(dir_path,'.gitignore'))
    elif 'vcs' not in no_ignore_set and 'parent' not in no_ignore_set and _has_git_ancestor(dir_path):
        files.append(os.path.join(dir_path,'.gitignore'))
    for fn in files:
        if os.path.isfile(fn):
            try:
                with open(fn,'r',encoding='utf-8',errors='ignore') as f:
                    for raw in f:
                        line=raw.rstrip('\n')
                        if not line or line.lstrip().startswith('#'): continue
                        neg=False
                        if line.startswith('!'): neg=True; line=line[1:]
                        patterns.append((line,neg,os.path.abspath(dir_path)))
            except OSError: pass
    # .git/info/exclude
    if 'exclude' not in no_ignore_set and 'vcs' not in no_ignore_set:
        # find .git in this dir
        gitdir=os.path.join(dir_path,'.git')
        if os.path.isdir(gitdir):
            fn=os.path.join(gitdir,'info','exclude')
            if os.path.isfile(fn):
                try:
                    with open(fn,'r',encoding='utf-8',errors='ignore') as f:
                        for raw in f:
                            line=raw.rstrip('\n')
                            if not line or line.lstrip().startswith('#'): continue
                            neg=line.startswith('!'); 
                            if neg: line=line[1:]
                            patterns.append((line,neg,os.path.abspath(dir_path)))
                except OSError: pass
    return patterns

def _matches_ignores(abs_path, is_dir, pattern_stack):
    matched=False
    for pat,neg,base in pattern_stack:
        try: rel=os.path.relpath(abs_path,base)
        except: continue
        if rel.startswith('..'): continue
        relp=rel.replace(os.sep,'/')
        if gitignore_match(pat, relp, is_dir):
            matched=not neg
    return matched

def _glob_decision(globs, rel_from_root, is_dir=False):
    # rel_from_root posix relative to a search root directory (or parent for file root)
    if not globs: return None
    has_positive=any(not g.startswith('!') for g in globs)
    decision=None; any_match=False
    for g in globs:
        neg=g.startswith('!')
        pat=g[1:] if neg else g
        # CLI globs: no-slash patterns match basename any level
        matched=False
        if pat.endswith('/'):
            # match a directory component
            if gitignore_match(pat, rel_from_root, is_dir or True): matched=True
            # also for a file under dir, gitignore_match handles parents
            if gitignore_match(pat, rel_from_root, is_dir): matched=True
        elif '/' not in pat:
            matched=glob_match(pat, rel_from_root.split('/')[-1])
        else:
            matched=glob_match(pat, rel_from_root)
        if matched:
            any_match=True; decision=not neg
    if not any_match:
        return False if has_positive else None
    return decision

def collect_files(paths, project, explicit_lang=None, follow=False, no_ignore=(), globs=(), allowed_langs=None, stderr_list=None):
    validate_globs(globs)
    no_ignore_set=set(no_ignore or [])
    entries=[]
    if not paths: paths=['.']
    for root_arg in paths:
        root_fs=root_arg
        if not os.path.exists(root_fs):
            msg=f"ERROR: {root_arg}: No such file or directory (os error 2)\n"
            if stderr_list is not None: stderr_list.append(msg)
            else: sys.stderr.write(msg)
            continue
        if os.path.isfile(root_fs) or (os.path.islink(root_fs) and not os.path.isdir(root_fs)):
            display=normalize_display(root_arg)
            lang=lang_for_file(root_fs, display, project)
            if explicit_lang and lang!=explicit_lang: 
                # custom languages etc: lang could be string name
                continue
            if allowed_langs is not None and lang not in allowed_langs:
                continue
            if lang is None: continue
            # globs on explicit file apply? likely yes like ripgrep override applies even to explicit files? We'll apply: if decision False skip
            parent=os.path.dirname(os.path.abspath(root_fs))
            rel=os.path.basename(root_fs)
            dec=_glob_decision(list(globs), rel, False)
            if dec is False:
                continue
            entries.append(FileEntry(display,root_fs,lang,root_arg))
            continue
        if os.path.isdir(root_fs):
            root_abs=os.path.abspath(root_fs)
            # parent ignores
            init_patterns=[]
            if 'parent' not in no_ignore_set:
                # ancestors of root, from topmost down to parent
                ancestors=[]
                cur=os.path.dirname(root_abs)
                while True:
                    ancestors.append(cur); parent=os.path.dirname(cur)
                    if parent==cur: break
                    cur=parent
                for anc in reversed(ancestors):
                    init_patterns.extend(_load_ignore_patterns(anc,no_ignore_set))
            # walk stack: (dir_abs, pattern_stack)
            stack=[(root_abs, init_patterns)]
            # For deterministic output, DFS with sorted names, then sort entries by display at end per root? We'll preserve walk order then caller may sort.
            local=[]
            while stack:
                dir_abs, pats_in = stack.pop()
                pats=pats_in+_load_ignore_patterns(dir_abs,no_ignore_set)
                try:
                    names=os.listdir(dir_abs)
                except OSError as e:
                    msg=f"ERROR: {dir_abs}: {os_error_str(e)}\n"
                    (stderr_list.append(msg) if stderr_list is not None else sys.stderr.write(msg)); continue
                names.sort()
                subdirs=[]
                for name in names:
                    child=os.path.join(dir_abs,name)
                    is_link=os.path.islink(child)
                    is_dir=os.path.isdir(child) and (follow or not is_link)
                    is_file=os.path.isfile(child)
                    # hidden dirs
                    rel_root=os.path.relpath(child,root_abs).replace(os.sep,'/')
                    gdec=_glob_decision(list(globs), rel_root, is_dir)
                    if is_dir:
                        if name.startswith('.') and 'hidden' not in no_ignore_set and gdec is not True:
                            continue
                        if gdec is False and _glob_decision(list(globs), rel_root, True) is False:
                            # If globs are in whitelist mode, still need descend to search for matching files unless dir is explicitly negated.
                            # Determine explicit exclusion: if a negated pattern matched dir, prune; otherwise descend.
                            explicit_exclude=False
                            for g in globs:
                                if g.startswith('!'):
                                    pat=g[1:]
                                    if ('/' not in pat and glob_match(pat,name)) or glob_match(pat,rel_root):
                                        explicit_exclude=True
                            if explicit_exclude: continue
                            # descend
                        if gdec is not True and _matches_ignores(child,True,pats):
                            continue
                        if is_link and not follow:
                            continue
                        subdirs.append((child,pats))
                    elif is_file:
                        if is_link and not follow:
                            # ignore crate: symlinked files are still followed? Test later; allow file symlinks inside tree? Ripgrep follows? We'll include file symlinks regardless follow for file entries except loops.
                            pass
                        # Hidden files are included (observed), hidden dirs only skipped
                        if gdec is False: continue
                        if gdec is not True and _matches_ignores(child,False,pats): continue
                        display=normalize_display(os.path.join(root_arg, rel_root)) if root_arg not in ('.','./') else normalize_display(rel_root)
                        lang=lang_for_file(child,display,project)
                        if lang is None: continue
                        if explicit_lang and lang!=explicit_lang: continue
                        if allowed_langs is not None and lang not in allowed_langs: continue
                        local.append(FileEntry(display,child,lang,root_arg))
                # push subdirs reverse to maintain sorted DFS
                for sd in reversed(subdirs): stack.append(sd)
            local.sort(key=lambda e:e.display)
            entries.extend(local)
    return entries

