    path=entry_or_path.fs_path if isinstance(entry_or_path,FileEntry) else entry_or_path
    with open(path,'rb') as f: data=f.read()
    # skip binary/non-utf8
    try:
        return data.decode('utf-8')
    except UnicodeDecodeError:
        return None
