def source_text(env, source):
    # source like $A or $$$A
    if not isinstance(source,str): return ''
    s=source.strip()
    multi=s.startswith('$$$')
    name=s.lstrip('$')
    if multi:
        from engine import meta_text_for_multi; return meta_text_for_multi(env,name)
    from engine import meta_text_for_single; return meta_text_for_single(env,name)

def apply_transforms(rc, env, ctx, target_node=None):
    if not isinstance(rc.transform,dict): return
