                cfg=tval['substring'] or {}; text=source_text(env,cfg.get('source',''))
                start=cfg.get('startChar'); end=cfg.get('endChar')
                n=len(text)
                sidx=0 if start is None else (start if start>=0 else max(0,n+start))
                eidx=n if end is None else (end if end>=0 else max(0,n+end))
                val=text[sidx:eidx] if eidx>=sidx else ''
            elif 'replace' in tval:
                cfg=tval['replace'] or {}; text=source_text(env,cfg.get('source',''))
                pat=str(cfg.get('replace','')); by=str(cfg.get('by',''))
                try:
