                    pyby=re.sub(r'\$\{(\d+|[A-Za-z_][A-Za-z0-9_]*)\}', r'\\g<\1>', by)
                    pyby=re.sub(r'\$(\d+)', r'\\g<\1>', pyby)
                    val=re.sub(pat, pyby, text)
                except re.error:
                    val=text
            elif 'convert' in tval:
                cfg=tval['convert'] or {}; text=source_text(env,cfg.get('source',''))
                val=convert_case(text, str(cfg.get('toCase','')), cfg.get('separatedBy'))
            elif 'rewrite' in tval:
                cfg=tval['rewrite'] or {}
                val=apply_rewrite_transform(cfg, env, rc, ctx)
        if val is not None:
