    return substitute_template(s,env)

def split_words(text, separators):
    if separators is None:
        seps={'caseChange','dash','underscore','dot','slash','space'}
    else:
        seps=set(separators or [])
    # split by explicit chars first
    chars=[]
    if 'dash' in seps: chars.append('-')
    if 'underscore' in seps: chars.append('_')
    if 'dot' in seps: chars.append('.')
    if 'slash' in seps: chars.append('/')
    if 'space' in seps: chars.append(' ')
    parts=[text]
    for ch in chars:
        new=[]
        for p in parts: new.extend(p.split(ch))
        parts=new
    if 'caseChange' in seps:
        new=[]
        for p in parts:
            # split lower->upper and acronym boundary
            idxs=[0]
            for i in range(1,len(p)):
                if p[i].isupper() and (p[i-1].islower() or p[i-1].isdigit()): idxs.append(i)
                elif p[i].isupper() and p[i-1].isupper() and i+1<len(p) and p[i+1].islower(): idxs.append(i)
            idxs.append(len(p))
            for a,b in zip(idxs,idxs[1:]): new.append(p[a:b])
        parts=new
    return [p for p in parts if p!='']

def convert_case(text, to_case, separated_by):
