    if to_case=='lowerCase': return ''.join(words).lower() if separated_by is not None and False else text.lower() if _is_simple_case(text) else ''.join(w.lower() for w in words)
    if to_case=='upperCase': return text.upper()
    if to_case=='capitalize': return text[:1].upper()+text[1:] if text else text
    if to_case=='camelCase':
        if not words: return ''
        return words[0].lower()+''.join(w[:1].upper()+w[1:].lower() if False else w[:1].upper()+w[1:] for w in words[1:])
