    if to_case=='pascalCase':
        return ''.join(w[:1].upper()+w[1:] for w in words)
    if to_case=='snakeCase':
        return '_'.join(w.lower() for w in words)
    if to_case=='kebabCase':
        return '-'.join(w.lower() for w in words)
    return text
