def apply_rewrite_transform(cfg, env, rc, ctx):
    src=cfg.get('source',''); rewriters=cfg.get('rewriters') or []; join_by=cfg.get('joinBy')
    # source could be multi $$$A -> operate on each captured node separately, or single node -> find submatches
    src_str=str(src); multi=src_str.startswith('$$$'); name=src_str.lstrip('$')
    source_nodes=[]
    if multi:
        source_nodes=list(env.multi.get(name,[]))
    elif name in env.single:
        source_nodes=[env.single[name]]
    else:
        return ''
    rw_configs=[]
    for rw_id in rewriters:
        rw=rc.rewriters.get(str(rw_id))
        if rw: rw_configs.append(rw)
    results=[]
    for snode in source_nodes:
        # if multi captured nodes include punctuation leaves, rewriters simply won't match them
        # For each source node, find all nodes in its subtree matching any rewriter (in traversal order) and collect their replacements. If a source node itself matches, that is one result.
        found=[]
        for candidate in all_nodes(snode):
            if not candidate.named: continue
            for rw in rw_configs:
                # build a transient RuleConfig-like context: rewriter has rule/fix; utils etc share rc utils
                try: m=build_matcher(rw.get('rule'), rc.language, rc)
                except Exception: continue
                e=MatchEnv()
                if m(candidate,e,ctx):
                    # constraints of rewriter
                    ok=True
                    if isinstance(rw.get('constraints'),dict):
                        for cname,crule in rw['constraints'].items():
                            cap=e.single.get(cname)
                            if cap is None: ok=False; break
                            cm=build_matcher(crule,rc.language,rc)
                            if not cm(cap,e,ctx): ok=False; break
                    if not ok: continue
                    # transforms in rewriter use same mechanism with temp rc shim
                    fix=rw.get('fix')
                    tmpl=fix if isinstance(fix,str) else (fix.get('template') if isinstance(fix,dict) else None)
                    if tmpl is not None:
                        found.append(substitute_template(str(tmpl),e,candidate,apply_indent=False))
                    break
        # If joinBy and multiple results from this source node, they'll be joined at top level too.
        results.extend(found)
    if join_by is not None:
        return str(join_by).join(results)
    return ''.join(results)

def generate_fix(rc, env, node, ctx):
    configs=rc.fix_configs()
    if not configs: return None
    cfg=configs[0]
    template=cfg.get('template') if isinstance(cfg,dict) else None
    if template is None: return None
    replacement=substitute_template(str(template),env,node,apply_indent=True)
    start=node.start; end=node.end
    # expandStart / expandEnd
    if isinstance(cfg,dict):
        if cfg.get('expandStart'):
            st=expand_range(node,cfg['expandStart'],'start',rc,ctx)
            if st is not None: start=st
        if cfg.get('expandEnd'):
            en=expand_range(node,cfg['expandEnd'],'end',rc,ctx)
            if en is not None: end=en
    return replacement, (start,end), configs

def expand_range(node, rel, direction, rc, ctx):
    # rel is Relation dict; search siblings before/after according to stopBy
    try: matcher=build_matcher(rel, rc.language, rc, in_relation=True)
    except Exception: return None
    stop=rel.get('stopBy','neighbor') if isinstance(rel,dict) else 'neighbor'
    parent=node.parent
    if parent is None: return None
    sibs=parent.children
    if node not in sibs: return None
    idx=sibs.index(node)
    if direction=='end':
        cand=sibs[idx+1:] if stop=='end' or isinstance(stop,dict) else sibs[idx+1:idx+2]
        # relation matcher may be just regex which our build_matcher allows (no positive kind check at build level). Match any node incl unnamed.
        for c in cand:
            e=MatchEnv()
            try:
                if matcher(c,e,ctx): return c.end
            except Exception: pass
            if isinstance(stop,dict):
