            e=MatchEnv()
            if matcher(c,e,ctx): return c.start
    return None

def evaluate_rule_on_doc(rc, doc):
    matcher=rc.get_matcher()
    ctx=Ctx(rc,doc)
    root=doc.parse(); out=[]
    for node in all_nodes(root):
        if not node.named: continue
