                seen.add(m)
                util=get_util_rule(rc,m)
                if util is not None: out.update(possible_kinds(util,lang,rc,seen))
    if isinstance(rule_data.get('all'),list):
        child_sets=[possible_kinds(x,lang,rc,seen_utils) for x in rule_data['all']]
        nonempty=[s for s in child_sets if s]
        if nonempty:
            inter=set.intersection(*nonempty) if len(nonempty)>1 else nonempty[0]
            # If intersection empty but all must hold, kinds could still be first's kinds as candidates for search (original may compute intersection and error if empty). Keep union as nonempty indicator to avoid false kind-set error.
            out.update(inter if inter else set().union(*nonempty))
    if isinstance(rule_data.get('any'),list):
        for x in rule_data['any']: out.update(possible_kinds(x,lang,rc,seen_utils))
    return out

def get_util_rule(rc, name):
    if isinstance(rc.utils,dict) and name in rc.utils: return rc.utils[name]
    if name in rc._global_utils: return rc._global_utils[name]
    return None

def compile_pattern_from_rule(pat, lang, rc=None):
    # cache on RuleConfig keyed by repr
    key=repr(pat)
    if rc is not None and key in rc._pattern_cache: return rc._pattern_cache[key]
    if isinstance(pat,str):
        root,doc=make_pattern(pat, lang)
    elif isinstance(pat,dict):
        context=pat.get('context')
        selector=pat.get('selector')
        if context is None:
            raise RuleLoadError(["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule contains invalid pattern matcher.","missing field `context`"])
        root,doc=make_pattern(str(context), lang, selector=selector, context_text=str(context))
        # pattern strictness stored separately by caller reading dict
    else:
        raise RuleLoadError(["Fail to parse yaml as Rule.","`rule` is not configured correctly.","Rule contains invalid pattern matcher.","invalid type: pattern must be a string or object"])
    if rc is not None: rc._pattern_cache[key]=(root,doc)
    return root,doc

def pattern_strictness_of(pat, default='smart'):
    if isinstance(pat,dict) and pat.get('strictness'): return str(pat['strictness'])
    return default

class Matcher:
    def __init__(self, fn): self.fn=fn
    def __call__(self, node, env, ctx): return self.fn(node,env,ctx)

class Ctx:
    def __init__(self, rc, root_doc):
        self.rc=rc; self.doc=root_doc

def _wrap_rule_error(kind_msg, inner_causes):
    return RuleLoadError(["Fail to parse yaml as Rule.","`rule` is not configured correctly.",kind_msg]+inner_causes)

def build_matcher(rule_data, lang, rc, top=False, in_relation=False):
    if not isinstance(rule_data,dict):
        raise _wrap_rule_error("Rule must have one positive matcher.",[])
    if len(rule_data)==0:
        raise _wrap_rule_error("Rule must have one positive matcher.",[])
    # Pre-validate subparts eagerly
    compiled={}
    # regex compile (translate Rust regex to Python roughly)
    regex_obj=None
    if 'regex' in rule_data and rule_data['regex'] is not None:
        try:
            regex_obj=re.compile(str(rule_data['regex']))
        except re.error as e:
            pat=str(rule_data['regex'])
            # emulate rust messages for common '['
            if pat=='[':
                cause="regex parse error:\n    [\n    ^\nerror: unclosed character class"
            else:
                cause=f"regex parse error:\n    {pat}\n    ^\nerror: {e.msg}"
            raise _wrap_rule_error("Rule contains invalid regex matcher.",["Parsing text matcher fails.",cause])
    if 'kind' in rule_data and rule_data['kind'] is not None:
        kind=str(rule_data['kind'])
        ks=KINDS.get(lang)
        from languages import ROOT_KIND
        if ks is not None and kind not in ks and kind not in (ROOT_KIND.get(lang),'ERROR'):
            raise _wrap_rule_error("Rule contains invalid kind matcher.",["Invalid Kind",f"Kind `{kind}` is invalid."])
    pat_root=None; pat_doc=None; pat_strict='smart'
    if 'pattern' in rule_data and rule_data['pattern'] is not None:
        try:
            pat_root,pat_doc=compile_pattern_from_rule(rule_data['pattern'], lang, rc)
            pat_strict=pattern_strictness_of(rule_data['pattern'])
        except PatternError as e:
            raise _wrap_rule_error("Rule contains invalid pattern matcher.",[e.cause])
        except RuleLoadError:
            raise
        except Exception as e:
            raise _wrap_rule_error("Rule contains invalid pattern matcher.",[str(e)])
    # sub matchers
    subs={}
    for key in ('inside','has','precedes','follows','not'):
        if key in rule_data and rule_data[key] is not None:
            subs[key]=build_matcher(rule_data[key],lang,rc,in_relation=(key!='not'))
    all_subs=[]
    if isinstance(rule_data.get('all'),list):
        all_subs=[build_matcher(x,lang,rc) for x in rule_data['all']]
    any_subs=[]
    if isinstance(rule_data.get('any'),list):
        any_subs=[build_matcher(x,lang,rc) for x in rule_data['any']]
    util_matcher=None; util_name=None
    if 'matches' in rule_data and rule_data['matches'] is not None:
        m=rule_data['matches']
        if isinstance(m,str):
            util_name=m
            util=get_util_rule(rc,m)
            if util is None:
                raise _wrap_rule_error("Rule contains invalid matches reference.",[f"Rule `{m}` is not defined."])
            util_matcher=build_matcher(util,lang,rc)
        elif isinstance(m,dict):
            # SerializableMatches object format uncertain: mapping { ??? } - treat values?
            util_matcher=build_matcher(m,lang,rc)
    # nthChild parse/validate
    nth=None
    if 'nthChild' in rule_data and rule_data['nthChild'] is not None:
        nth=parse_nth_child(rule_data['nthChild'], lang, rc)
    rng=rule_data.get('range')
    def fn(node, env, ctx):
        # Each key present is ANDed.
        local=env.copy()
        if pat_root is not None:
            if not match_node(pat_root,node,local,pat_strict): return False
        if 'kind' in rule_data and rule_data['kind'] is not None:
            if node.ext_kind!=str(rule_data['kind']): return False
        if regex_obj is not None:
            if not regex_obj.search(node.text()): return False
        if nth is not None:
            if not check_nth_child(node,nth,ctx): return False
        if rng is not None:
            if not check_range(node,rng): return False
        # composites
        for sm in all_subs:
            if not sm(node,local,ctx): return False
        if 'any' in rule_data:
            if not any_subs:
                return False
            ok=False
            for sm in any_subs:
                env2=local.copy()
                if sm(node,env2,ctx): local=env2; ok=True; break
            if not ok: return False
        if util_matcher is not None:
            if not util_matcher(node,local,ctx): return False
        # relations
        if 'inside' in subs:
            rel=rule_data['inside']; 
            if not match_relation(node, rel, subs['inside'], 'inside', local, ctx): return False
        if 'has' in subs:
            rel=rule_data['has']
            if not match_relation(node, rel, subs['has'], 'has', local, ctx): return False
        if 'precedes' in subs:
            if not match_relation(node, rule_data['precedes'], subs['precedes'], 'precedes', local, ctx): return False
        if 'follows' in subs:
            if not match_relation(node, rule_data['follows'], subs['follows'], 'follows', local, ctx): return False
        if 'not' in subs:
            env_not=local.copy()
            if subs['not'](node,env_not,ctx): return False
        env.assign_from(local); return True
    return Matcher(fn)

def parse_nth_child(data, lang, rc):
    # return dict(a,b,reverse,of_matcher, simple)
    if isinstance(data,dict):
        pos=data.get('position'); reverse=bool(data.get('reverse',False)); of=data.get('ofRule')
        of_matcher=build_matcher(of,lang,rc) if isinstance(of,dict) else None
        a,b=_parse_nth_expr(pos)
        return {'a':a,'b':b,'reverse':reverse,'of':of_matcher}
    else:
        a,b=_parse_nth_expr(data)
        return {'a':a,'b':b,'reverse':False,'of':None}

def _parse_nth_expr(pos):
    if isinstance(pos,int):
        return (0,pos)
    s=str(pos).strip().replace(' ','')
    if re.fullmatch(r'\d+',s): return (0,int(s))
    # An+B, An-B, n, -n+3 etc. Reject letters other than n
    for ch in s:
        if ch.isalpha() and ch!='n':
            raise _wrap_rule_error("Rule contains invalid nthChild matcher.",[f"Illegal character {ch} encountered"])
    m=re.fullmatch(r'([+-]?\d*)n(?:([+-]\d+))?',s)
    if not m:
        raise _wrap_rule_error("Rule contains invalid nthChild matcher.",[f"Illegal character {s[0] if s else ''} encountered"])
    a_str=m.group(1); b_str=m.group(2)
    if a_str in ('','+'): a=1
    elif a_str=='-': a=-1
    else: a=int(a_str)
    b=int(b_str) if b_str else 0
    return a,b

def _nth_matches(a,b,index1):
    # index1 is 1-based position. CSS An+B matches if exists n>=0 with An+B=index
    if a==0: return index1==b
    diff=index1-b
    if diff%a!=0: return False
    return diff//a>=0

def check_nth_child(node,nth,ctx):
    parent=node.parent
    if parent is None: return False
    siblings=[c for c in parent.children if c.named]
    if nth.get('of') is not None:
        filtered=[]
        for sib in siblings:
            e=MatchEnv()
            if nth['of'](sib,e,ctx): filtered.append(sib)
        siblings=filtered
    if node not in siblings: return False
    idx=siblings.index(node)+1
    if nth.get('reverse'):
        idx=len(siblings)-idx+1
    return _nth_matches(nth['a'],nth['b'],idx)

def check_range(node,rng):
    if not isinstance(rng,dict): return False
    def pos_match(node_pos, spec):
        line,col=node_pos
        if spec is None: return True
        if not isinstance(spec,dict): return False
        if spec.get('line') is not None and int(spec['line'])!=line: return False
        if spec.get('column') is not None and int(spec['column'])!=col: return False
        return True
    s=node.doc.line_col(node.start); e=node.doc.line_col(node.end)
    return pos_match(s,rng.get('start')) and pos_match(e,rng.get('end'))

def _stopby(rel):
    if isinstance(rel,dict): return rel.get('stopBy','neighbor')
    return 'neighbor'

def _field_filter(nodes, rel):
    field=rel.get('field') if isinstance(rel,dict) else None
    if not field: return nodes
    return [n for n in nodes if n.field==field]

def match_relation(node, rel, matcher, kind, env, ctx):
    stop=_stopby(rel)
    # Build candidate list in search order
    candidates=[]
    field=rel.get('field') if isinstance(rel,dict) else None
    def consider(n):
        if n is None: return
        if field and n.field!=field: return
        candidates.append(n)
    if kind=='inside':
        if stop=='end':
            cur=node.parent
            while cur is not None: consider(cur); cur=cur.parent
        elif isinstance(stop,dict):
            # go up until a node matching stop rule (inclusive? stop when encountered after checking? semantics: search until stopBy node)
            stop_matcher=build_matcher(stop, ctx.rc.language, ctx.rc)
            cur=node.parent
            while cur is not None:
                consider(cur)
                e=MatchEnv()
                if stop_matcher(cur,e,ctx): break
                cur=cur.parent
        else: # neighbor
            if field:
                # find ancestor (?) field refers immediate parent's field? Original inside field: target must be inside a node that is field X of its parent? Hmm: Relation.field means the *related node* is accessed via field of target's parent chain? For inside, field restricts node's own field in parent? We'll approximate: if node's field != field and parent candidate check still; node field check done here
                pass
            consider(node.parent)
    elif kind=='has':
        if stop=='end':
            for n in all_nodes(node):
                if n is not node: consider(n)
        elif isinstance(stop,dict):
            stop_matcher=build_matcher(stop, ctx.rc.language, ctx.rc)
            # BFS down until stop nodes not descended
            stack=list(node.children)
            while stack:
                n=stack.pop(0); consider(n)
                e=MatchEnv()
                if stop_matcher(n,e,ctx): continue
                stack[0:0]=list(n.children)
        else:
            for n in node.children: consider(n)
    elif kind=='precedes':
        sibs=node.parent.children if node.parent else []
        named_sibs=[c for c in sibs if c.named]
        # relations operate on named siblings? Target node's following siblings in parent's named children.
        if node in named_sibs:
            idx=named_sibs.index(node)
            following=named_sibs[idx+1:]
        else:
            following=[]
        if stop=='end':
            for n in following: consider(n)
        elif isinstance(stop,dict):
            stop_matcher=build_matcher(stop, ctx.rc.language, ctx.rc)
            for n in following:
                consider(n); e=MatchEnv()
                if stop_matcher(n,e,ctx): break
        else:
            if following: consider(following[0])
    elif kind=='follows':
        sibs=node.parent.children if node.parent else []
        named_sibs=[c for c in sibs if c.named]
        preceding=[]
        if node in named_sibs:
            idx=named_sibs.index(node); preceding=list(reversed(named_sibs[:idx]))
        if stop=='end':
            for n in preceding: consider(n)
        elif isinstance(stop,dict):
            stop_matcher=build_matcher(stop, ctx.rc.language, ctx.rc)
            for n in preceding:
                consider(n); e=MatchEnv()
                if stop_matcher(n,e,ctx): break
        else:
            if preceding: consider(preceding[0])
    for cand in candidates:
        env2=env.copy()
        if matcher(cand,env2,ctx):
            env.assign_from(env2); return True
    return False

# ---- transforms ----
def source_text(env, source):
    # source like $A or $$$A
    if not isinstance(source,str): return ''
    s=source.strip()
    multi=s.startswith('$$$')
    name=s.lstrip('$')
    if multi:
        from engine import meta_text_for_multi; return meta_text_for_multi(env,name)
    from engine import meta_text_for_single; return meta_text_for_single(env,name)

def apply_transforms(rc, env, ctx, target_node=None):
    if not isinstance(rc.transform,dict): return
    for new_name, tval in rc.transform.items():
        val=None
        if isinstance(tval,str):
            val=apply_transform_string(tval, env, rc, ctx)
        elif isinstance(tval,dict):
            if 'substring' in tval:
                cfg=tval['substring'] or {}; text=source_text(env,cfg.get('source',''))
                start=cfg.get('startChar'); end=cfg.get('endChar')
                n=len(text)
                sidx=0 if start is None else (start if start>=0 else max(0,n+start))
                eidx=n if end is None else (end if end>=0 else max(0,n+end))
                val=text[sidx:eidx] if eidx>=sidx else ''
            elif 'replace' in tval:
                cfg=tval['replace'] or {}; text=source_text(env,cfg.get('source',''))
                pat=str(cfg.get('replace','')); by=str(cfg.get('by',''))
                try:
                    # Rust regex replacement uses $1 / ${1}; convert to python \g<1> carefully both forms already supported in tests gave same.
                    pyby=re.sub(r'\$\{(\d+|[A-Za-z_][A-Za-z0-9_]*)\}', r'\\g<\1>', by)
                    pyby=re.sub(r'\$(\d+)', r'\\g<\1>', pyby)
                    val=re.sub(pat, pyby, text)
                except re.error:
                    val=text
            elif 'convert' in tval:
                cfg=tval['convert'] or {}; text=source_text(env,cfg.get('source',''))
                val=convert_case(text, str(cfg.get('toCase','')), cfg.get('separatedBy'))
            elif 'rewrite' in tval:
                cfg=tval['rewrite'] or {}
                val=apply_rewrite_transform(cfg, env, rc, ctx)
        if val is not None:
            env.transformed[str(new_name)]=val

def apply_transform_string(s, env, rc, ctx):
    # Support simple forms we can infer; unknown strings return substituted template
    return substitute_template(s,env)

def split_words(text, separators):
    if separators is None:
        seps={'caseChange','dash','underscore','dot','slash','space'}
    else:
        seps=set(separators or [])
    # split by explicit chars first
    chars=[]
    if 'dash' in seps: chars.append('-')
    if 'underscore' in seps: chars.append('_')
    if 'dot' in seps: chars.append('.')
    if 'slash' in seps: chars.append('/')
    if 'space' in seps: chars.append(' ')
    parts=[text]
    for ch in chars:
        new=[]
        for p in parts: new.extend(p.split(ch))
        parts=new
    if 'caseChange' in seps:
        new=[]
        for p in parts:
            # split lower->upper and acronym boundary
            idxs=[0]
            for i in range(1,len(p)):
                if p[i].isupper() and (p[i-1].islower() or p[i-1].isdigit()): idxs.append(i)
                elif p[i].isupper() and p[i-1].isupper() and i+1<len(p) and p[i+1].islower(): idxs.append(i)
            idxs.append(len(p))
            for a,b in zip(idxs,idxs[1:]): new.append(p[a:b])
        parts=new
    return [p for p in parts if p!='']

def convert_case(text, to_case, separated_by):
    words=split_words(text, separated_by)
    if to_case=='lowerCase': return ''.join(words).lower() if separated_by is not None and False else text.lower() if _is_simple_case(text) else ''.join(w.lower() for w in words)
    if to_case=='upperCase': return text.upper()
    if to_case=='capitalize': return text[:1].upper()+text[1:] if text else text
    if to_case=='camelCase':
        if not words: return ''
        return words[0].lower()+''.join(w[:1].upper()+w[1:].lower() if False else w[:1].upper()+w[1:] for w in words[1:])
        # note words from caseChange preserve internal caps? original convert for user_accountName with underscore only gave userAccountName (N preserved because AccountName word capitalized -> AccountName). Good.
    if to_case=='pascalCase':
        return ''.join(w[:1].upper()+w[1:] for w in words)
    if to_case=='snakeCase':
        return '_'.join(w.lower() for w in words)
    if to_case=='kebabCase':
        return '-'.join(w.lower() for w in words)
    return text
def _is_simple_case(s): return True

def apply_rewrite_transform(cfg, env, rc, ctx):
    src=cfg.get('source',''); rewriters=cfg.get('rewriters') or []; join_by=cfg.get('joinBy')
    # source could be multi $$$A -> operate on each captured node separately, or single node -> find submatches
    src_str=str(src); multi=src_str.startswith('$$$'); name=src_str.lstrip('$')
    source_nodes=[]
    if multi:
        source_nodes=list(env.multi.get(name,[]))
    elif name in env.single:
        source_nodes=[env.single[name]]
    else:
        return ''
    rw_configs=[]
    for rw_id in rewriters:
        rw=rc.rewriters.get(str(rw_id))
        if rw: rw_configs.append(rw)
    results=[]
    for snode in source_nodes:
        # if multi captured nodes include punctuation leaves, rewriters simply won't match them
        # For each source node, find all nodes in its subtree matching any rewriter (in traversal order) and collect their replacements. If a source node itself matches, that is one result.
        found=[]
        for candidate in all_nodes(snode):
            if not candidate.named: continue
            for rw in rw_configs:
                # build a transient RuleConfig-like context: rewriter has rule/fix; utils etc share rc utils
                try: m=build_matcher(rw.get('rule'), rc.language, rc)
                except Exception: continue
                e=MatchEnv()
                if m(candidate,e,ctx):
                    # constraints of rewriter
                    ok=True
                    if isinstance(rw.get('constraints'),dict):
                        for cname,crule in rw['constraints'].items():
                            cap=e.single.get(cname)
                            if cap is None: ok=False; break
                            cm=build_matcher(crule,rc.language,rc)
                            if not cm(cap,e,ctx): ok=False; break
                    if not ok: continue
                    # transforms in rewriter use same mechanism with temp rc shim
                    fix=rw.get('fix')
                    tmpl=fix if isinstance(fix,str) else (fix.get('template') if isinstance(fix,dict) else None)
                    if tmpl is not None:
                        found.append(substitute_template(str(tmpl),e,candidate,apply_indent=False))
                    break
        # If joinBy and multiple results from this source node, they'll be joined at top level too.
        results.extend(found)
    if join_by is not None:
        return str(join_by).join(results)
    return ''.join(results)

def generate_fix(rc, env, node, ctx):
    configs=rc.fix_configs()
    if not configs: return None
    cfg=configs[0]
    template=cfg.get('template') if isinstance(cfg,dict) else None
    if template is None: return None
    replacement=substitute_template(str(template),env,node,apply_indent=True)
    start=node.start; end=node.end
    # expandStart / expandEnd
    if isinstance(cfg,dict):
        if cfg.get('expandStart'):
            st=expand_range(node,cfg['expandStart'],'start',rc,ctx)
            if st is not None: start=st
        if cfg.get('expandEnd'):
            en=expand_range(node,cfg['expandEnd'],'end',rc,ctx)
            if en is not None: end=en
    return replacement, (start,end), configs

def expand_range(node, rel, direction, rc, ctx):
    # rel is Relation dict; search siblings before/after according to stopBy
    try: matcher=build_matcher(rel, rc.language, rc, in_relation=True)
    except Exception: return None
    stop=rel.get('stopBy','neighbor') if isinstance(rel,dict) else 'neighbor'
    parent=node.parent
    if parent is None: return None
    sibs=parent.children
    if node not in sibs: return None
    idx=sibs.index(node)
    if direction=='end':
        cand=sibs[idx+1:] if stop=='end' or isinstance(stop,dict) else sibs[idx+1:idx+2]
        # relation matcher may be just regex which our build_matcher allows (no positive kind check at build level). Match any node incl unnamed.
        for c in cand:
            e=MatchEnv()
            try:
                if matcher(c,e,ctx): return c.end
            except Exception: pass
            if isinstance(stop,dict):
                # stop semantics complex; continue
                pass
    else:
        cand=list(reversed(sibs[:idx])) if stop=='end' or isinstance(stop,dict) else list(reversed(sibs[max(0,idx-1):idx]))
        for c in cand:
            e=MatchEnv()
            if matcher(c,e,ctx): return c.start
    return None

def evaluate_rule_on_doc(rc, doc):
    matcher=rc.get_matcher()
    ctx=Ctx(rc,doc)
    root=doc.parse(); out=[]
    for node in all_nodes(root):
        if not node.named: continue
        env=MatchEnv()
        if matcher(node,env,ctx):
            # constraints
            ok=True
            if isinstance(rc.constraints,dict):
                for cname,crule in rc.constraints.items():
                    cap=env.single.get(cname)
                    if cap is None:
                        # multi constraint? skip/fail?
                        ok=False; break
                    cm=build_matcher(crule,rc.language,rc)
                    # constraint env merges
                    if not cm(cap,env,ctx): ok=False; break
            if not ok: continue
            apply_transforms(rc,env,ctx,node)
            out.append((node,env))
    return out

def rule_applies_to_path(rc, path_for_glob):
    # files allow list, ignores deny list; entries can be string or {glob,caseInsensitive}
    def entries(v):
        if not v: return []
        out=[]
        for x in v:
            if isinstance(x,dict): out.append((str(x.get('glob','')), bool(x.get('caseInsensitive',False))))
            else: out.append((str(x),False))
        return out
    files=entries(rc.files)
    if files:
        if not any(glob_match(p,path_for_glob,ci) for p,ci in files): return False
    ignores=entries(rc.ignores)
    if ignores:
        if any(glob_match(p,path_for_glob,ci) for p,ci in ignores): return False
    return True

def load_rules_from_project(project):
    rules=[]; global_utils={}; util_rule_configs=[]
    # util dirs first
    for ud in project.util_dirs():
        absdir=ud if os.path.isabs(ud) else os.path.join(project.project_dir or os.getcwd(), ud)
        if not os.path.isdir(absdir):
            raise AppError(6, format_app_error(f"Cannot read util directory {os.path.abspath(absdir)}","The util directory cannot be read or traversed",None,[f"{os.path.abspath(absdir)}: IO error for operation on {os.path.abspath(absdir)}: No such file or directory (os error 2)"]))
        for path in _walk_yaml(absdir):
