    def _read_key(self):
        if sys.stdin.isatty():
            import termios, tty
            fd=sys.stdin.fileno(); old=termios.tcgetattr(fd)
            try:
                tty.setraw(fd); ch=os.read(fd,1)
            finally:
                termios.tcsetattr(fd, termios.TCSADRAIN, old)
            return ch
        else:
            ch=os.read(0,1)
            return ch
