        prompt_text="Accept? [y]es/[↵], [n]o, [a]ll, [q]uit, [e]dit" if kind=='rewrite' else "Next[enter], Quit[q], Edit[e]"
        sys.stdout.write("\x1b[?1049h\x1b[2J\x1b[1;1H"+content+prompt_text); sys.stdout.flush()
        while True:
            ch=self._read_key()
            if not ch:
                sys.stdout.write("\x1b[?1049l"); return 'q'
            c=ch.decode('utf-8',errors='ignore')
            if kind=='rewrite':
                if c in ('y','\r'): sys.stdout.write("\x1b[?1049l"); return 'y'
                if c=='n': sys.stdout.write("\x1b[?1049l"); return 'n'
                if c=='a': sys.stdout.write("\x1b[?1049l"); return 'a'
                if c=='q': sys.stdout.write("\x1b[?1049l"); return 'q'
