def new_project(opts,name=None):
    # if already in project (ancestor sgconfig) error 17 regardless config arg? If explicit -c exists?
    proj=find_project(opts.get('config'),required=False) if not opts.get('config') else None
    if opts.get('config'):
        # if config file file given exists as project - treat exists? Use find behavior: if file doesn't exist find_project raises more relevant? For new project -c custom path maybe creates that config file path. Implement: if custom config exists -> project exists; if not, create at that path and dirs relative to its parent using defaults.
        cfg_path=opts.get('config')
        if os.path.exists(cfg_path):
            raise AppError(17, format_app_error("ast-grep project already exists.","You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?","https://ast-grep.github.io/guide/scan-project.html"))
        return _create_project(custom_config=cfg_path)
    if proj and proj.is_project:
        raise AppError(17, format_app_error("ast-grep project already exists.","You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?","https://ast-grep.github.io/guide/scan-project.html"))
    return _create_project()

def _create_project(custom_config=None, quiet_prefix=None):
    cwd=os.getcwd()
    if custom_config:
        config_path=os.path.abspath(custom_config); base=os.path.dirname(config_path)
    else:
        config_path=os.path.join(cwd,'sgconfig.yml'); base=cwd
    # Messages: caller for `new` no entity no project with -y needs prefix "No sgconfig.yml found. Creating..."
    if quiet_prefix: sys.stdout.write(quiet_prefix)
    sys.stdout.write("Creating a new ast-grep project...\n")
    rules_dir=os.path.join(base,'rules'); tests_dir=os.path.join(base,'rule-tests'); utils_dir=os.path.join(base,'utils')
    for d in (rules_dir,tests_dir,utils_dir): os.makedirs(d,exist_ok=True)
    for d in (rules_dir,tests_dir,utils_dir):
        keep=os.path.join(d,'.gitkeep')
        if not os.path.exists(keep): open(keep,'w').close()
    content=f"ruleDirs:\n- {rules_dir}\ntestConfigs:\n- testDir: {tests_dir}\nutilDirs:\n- {utils_dir}\n"
    with open(config_path,'w',encoding='utf-8') as f: f.write(content)
    sys.stdout.write("Your new ast-grep project has been created!\n")
    return 0

