    if entity=='rule':
        dirs=proj.rule_dirs()
        if not dirs:
            raise AppError(1,"Error: No rule directories are configured.\n")
        target_dir=dirs[0] if os.path.isabs(dirs[0]) else os.path.join(proj.project_dir,dirs[0])
        path=os.path.join(target_dir,f"{name}.yml")
        _check_not_exists(path)
        os.makedirs(target_dir,exist_ok=True)
        content=f"""# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json

id: {name}
message: Add your rule message here....
severity: error # error, warning, info, hint
language: {lang}
rule:
  pattern: Your Rule Pattern here...
