# note: Add detailed explanation for the rule."""
        with open(path,'w',encoding='utf-8') as f: f.write(content)
        sys.stdout.write(f"Created rules at {os.path.abspath(path)}\n")
        # also create test if testConfigs present
        tcs=proj.test_configs()
        if tcs:
            td=tcs[0].get('testDir')
            if td:
                abs_td=td if os.path.isabs(td) else os.path.join(proj.project_dir,td)
