        return 0
    else:
        dirs=proj.util_dirs()
        if not dirs:
            raise AppError(1,"Error: No util directories are configured.\n")
        target_dir=dirs[0] if os.path.isabs(dirs[0]) else os.path.join(proj.project_dir,dirs[0])
        path=os.path.join(target_dir,f"{name}.yml"); _check_not_exists(path); os.makedirs(target_dir,exist_ok=True)
        content=f"""id: {name}
language: {lang}
rule:
  pattern: Your Rule Pattern here...
# utils: Extract repeated rule as local utility here."""
        with open(path,'w',encoding='utf-8') as f: f.write(content)
        sys.stdout.write(f"Created util at {os.path.abspath(path)}\n")
        return 0

