    if cmd=='new':
        return new_dispatch(rest)
    # unrecognized subcommand
    spec=SPECS['root']
    cand=similar(cmd, list(spec.subcommands))
    tip=f"a similar subcommand exists: '{cand}'" if cand else None
    raise ClapExit(2,'',format_error(f"unrecognized subcommand '{cmd}'",spec,tip=tip,usage=spec.canonical_usage()))

def help_dispatch(args):
    if not args:
        sys.stdout.write(help_text('root','long')); return 0
    # help help
    if args==['help']:
        from help_data import HELP_DATA; sys.stdout.write(HELP_DATA['help_help'].replace('{BIN}',cli.BIN)); return 0
    cmd=args[0]
    if cmd in ('run','scan','test','lsp','completions'):
        if len(args)>1:
            spec=SPECS[cmd]; raise ClapExit(2,'',format_error(f"unrecognized subcommand '{args[1]}'",spec,usage=spec.canonical_usage()))
        sys.stdout.write(help_text(cmd,'long')); return 0
    if cmd=='new':
        if len(args)==1:
            sys.stdout.write(help_text('new','long')); return 0
        if args[1] in ('project','rule','test','util'):
            if len(args)>2:
                spec=SPECS[f"new_{args[1]}"]; raise ClapExit(2,'',format_error(f"unrecognized subcommand '{args[2]}'",spec,usage=spec.canonical_usage()))
            sys.stdout.write(help_text(f"new_{args[1]}",'long')); return 0
        if args[1]=='help':
            if len(args)==2:
                from help_data import HELP_DATA; sys.stdout.write(HELP_DATA['new_help_help'].replace('{BIN}',cli.BIN)); return 0
            # help new help <sub> ??? original maybe prints sub help; approximate
            return help_dispatch(['new']+args[2:])
        spec=SPECS['new']; raise ClapExit(2,'',format_error(f"unrecognized subcommand '{args[1]}'",spec,usage=spec.canonical_usage()))
    spec=SPECS['root']; raise ClapExit(2,'',format_error(f"unrecognized subcommand '{cmd}'",spec,usage=spec.canonical_usage()))

def new_dispatch(rest):
    # Structures: new [OPTIONS] [NAME] [COMMAND] and new <command> [OPTIONS] [NAME]
    # Clap parsing is unusual. We'll implement detection:
    entities=('project','rule','test','util')
    # Handle help subcommand under new
    if rest and rest[0]=='help':
        if len(rest)==1:
            sys.stdout.write(help_text('new','long')); return 0
        if len(rest)==2 and rest[1]=='help':
            from help_data import HELP_DATA; sys.stdout.write(HELP_DATA['new_help_help'].replace('{BIN}',cli.BIN)); return 0
        if len(rest)>=2 and rest[1] in entities:
            sys.stdout.write(help_text(f"new_{rest[1]}",'long')); return 0
        spec=SPECS['new']; raise ClapExit(2,'',format_error(f"unrecognized subcommand '{rest[1]}'",spec,usage=spec.canonical_usage()))
    if rest and rest[0] in entities:
        ent=rest[0]; opts=parse_args(SPECS[f'new_{ent}'],rest[1:],max_positional=1)
        name=opts.positionals[0] if opts.positionals else None
        return new_command(opts,entity=ent,name=name)
    # Could be NAME then ENTITY (options can be interspersed? Original parse in new command itself)
    # Parse with new spec allowing up to 2 positionals, then interpret.
    opts=parse_args(SPECS['new'],rest,max_positional=2)
    pos=opts.positionals
    if not pos:
        # new -y in empty dir creates project (observed) even though entity missing logic says earlier new another -y in project gave entity insufficient.
        # Check project existence: if no project and yes (?) implementation inspired by original Default entity selection: if no sgconfig, create project.
        proj=find_project(opts.get('config'),required=False)
        if not proj.is_project and bool(opts.get('yes')):
            sys.stdout.write("No sgconfig.yml found. ")
            return _create_project(custom_config=opts.get('config'))
        return new_command(opts,entity=None,name=None)
    if len(pos)==1:
        # Single positional could be NAME only (entity missing). Original `new unknown -y` -> entity insufficient.
        # If positional is entity name handled above; so it's name.
        return new_command(opts,entity=None,name=pos[0])
    # two positionals: one is entity, one name, order either (name, entity) if second in entities; or unknown extra triggers parse_args max? new NAME COMMAND syntax means second is command. If second not entity, original clap would error unrecognized subcommand? We'll treat entity unknown via new_command yes error or TTY.
    name,ent=pos[0],pos[1]
    if ent in entities:
        return new_command(opts,entity=ent,name=name)
    # maybe ent is name and??? first is entity handled if first starts args but options interspersed could make po order entity,name
    if name in entities:
        return new_command(opts,entity=name,name=ent)
    return new_command(opts,entity=None,name=name)
