# ---------- debug query ----------
def debug_tree_text(doc, pat_root, fmt):
    root=doc.parse()
    if fmt=='pattern':
        lines=[]
        def rec(n,indent):
            pre='  '*indent
            if n.meta:
                lines.append(f"{pre}MetaVar {n.meta.get('display')}")
                return
            if n.coarse=='string':
                # check entire content meta
                contents=[c for c in n.children if c.token_type=='string_content']
                # fallthrough generic would show content
            if n.is_leaf():
                if n.named:
                    lines.append(f"{pre}{n.ext_kind} {n.text()}")
                else:
                    lines.append(f"{pre}{n.text()}")
                return
            lines.append(f"{pre}{n.ext_kind}")
            for c in n.children: rec(c,indent+1)
        rec(pat_root,0)
        return '\n'.join(lines)+'\n'
    if fmt in ('ast','cst'):
        named_only=(fmt=='ast')
        lines=[]
        def rec(n,indent):
            if named_only and not n.named: return
            sl,sc=doc.line_col(n.start); el,ec=doc.line_col(n.end)
            label=n.ext_kind if (n.named or not n.is_leaf()) else n.text()
            field_prefix=f"{n.field}: " if n.field else ''
            # In AST, field prefix only for named; CST can have for unnamed operator etc (we set some)
            lines.append(f"{'  '*indent}{field_prefix}{label} ({sl},{sc})-({el},{ec})")
            for c in n.children: rec(c,indent+1)
        rec(root,0)
        return '\n'.join(lines)+'\n'
    if fmt=='sexp':
        def rec(n):
            if not n.named: return ''
            inner=''
            for c in n.children:
                if not c.named: continue
                cs=rec(c)
                if c.field: inner+=f" {c.field}: {cs}"
                else: inner+=f" {cs}"
            return f"({n.ext_kind}{inner})"
        return rec(root)+'\n'
    return ''

