            if rewrite is not None:
                replacement=substitute_template(rewrite,env,node,apply_indent=True)
                repl_off=(node.start,node.end)
            m=make_match_dict(node,env,file_display,text,lang,replacement=replacement,repl_offsets=repl_off)
            # store fs_path
            m['fs_path']=fs_path
            all_matches.append(m)
    if inspect=='entity' and not use_stdin:
        for file_display,lang in entities:
            eprint(f"sg: entity|file|{file_display}: language={lang}\n")
    if inspect!='nothing':
        eprint(f"sg: summary|file: scannedFileCount={scanned if not use_stdin else 0},skippedFileCount={skipped if not use_stdin else 0}\n")
    # prepare JSON offsets conversion in match_to_json: it expects replacement_offsets as byte offsets. Our matches have char offsets; adjust before JSON output by converting temporarily at dump time: monkey by setting attribute expected.
    # Instead build JSON copy matches
    def json_ready(matches):
        out=[]
        for m in matches:
            mm=dict(m)
            if mm.get('replacement') is not None:
                mm['replacement_offsets']=rewrite_offsets_json(m)
            out.append(mm)
        return out
    # pattern error warning determination
    has_error=False
    for lang,doc in pattern_docs.items():
        if pattern_has_error_from_doc(doc): has_error=True
    # outputs
    color_enabled=should_color(opts.get('color','auto'), sys.stdout.isatty())
    if json_style:
        sys.stdout.write(dump_json_matches(json_ready(all_matches), json_style))
        return _finish_run(all_matches,has_error)
    if files_with:
        seen=[]
        for m in all_matches:
            if m['file'] not in seen: seen.append(m['file'])
        for f in seen: sys.stdout.write(f+"\n")
        return _finish_run(all_matches,has_error)
    # rewrite handling
    if rewrite is not None:
        if use_stdin:
            handle_stdin_rewrite(all_matches, sources[0][3] if sources else '', opts, color_enabled)
            return _finish_run(all_matches,has_error)
        if interactive:
            applied=handle_interactive_rewrites(all_matches, opts, color_enabled, mode='run')
            return _finish_run(all_matches,has_error)
        if update_all:
            applied=apply_rewrites_to_files(all_matches)
            if applied: eprint(f"Applied {applied} changes\n")
            return _finish_run(all_matches,has_error)
        # print combined diffs per file
        for file_display,doc_text,matches in group_matches_by_file(all_matches):
            sys.stdout.write((f"\x1b[3;36m{file_display}\x1b[0m\n" if color_enabled else f"{file_display}\n"))
            new_text,applied=apply_edits(doc_text, build_edits_for_matches(matches))
            sys.stdout.write(make_diff(doc_text,new_text,color=color_enabled))
        return _finish_run(all_matches,has_error)
    # plain search; if interactive without rewrite, original shows matches interactively with Next prompt
    if interactive and all_matches:
        # Show plain match lines through interactive prompt per match (scan-like)
        handle_interactive_view(all_matches, opts, color_enabled)
        return _finish_run(all_matches,has_error)
    print_matches_plain(group_matches_by_file(all_matches), opts, color_enabled)
    return _finish_run(all_matches,has_error)

def _finish_run(all_matches, has_error=False):
    if all_matches: return 0
    if has_error:
        eprint("Warning: Pattern contains an ERROR node and may cause unexpected results.\nHelp: ast-grep parsed the pattern but it matched nothing in this run. Try using playground to refine the pattern.\nSee also: https://ast-grep.github.io/playground.html\n\n")
        return 0
    return 1

def handle_stdin_rewrite(all_matches, text, opts, color=False):
    update_all=bool(opts.get('update_all')); interactive=bool(opts.get('interactive'))
    if interactive:
        # interactive with stdin: prompt per match, then if accepted print result? Original stdin interactive not probed; treat as interactive files with fake path
        applied=handle_interactive_rewrites(all_matches, opts, color, mode='stdin')
        return
    if update_all:
        if not all_matches: return
        new_text,applied=apply_edits(text, build_edits_for_matches(all_matches))
        sys.stdout.write(new_text+"\n")
        eprint(f"Applied {len(applied)} changes\n")
        return
    # diff
    if not all_matches: return
    sys.stdout.write((f"\x1b[3;36mSTDIN\x1b[0m\n" if color else "STDIN\n"))
    new_text,applied=apply_edits(text, build_edits_for_matches(all_matches))
    sys.stdout.write(make_diff(text,new_text,color=color))

def apply_rewrites_to_files(all_matches):
    applied_total=0
    for file_display,doc_text,matches in group_matches_by_file(all_matches):
        fs_path=matches[0].get('fs_path') if matches else None
        new_text,applied=apply_edits(doc_text, build_edits_for_matches(matches))
        if applied and fs_path:
            with open(fs_path,'w',encoding='utf-8',newline='') as f: f.write(new_text)
            applied_total+=len(applied)
    return applied_total

def handle_interactive_rewrites(all_matches, opts, color=False, mode='run'):
    session=Interactive(); applied=0; accept_all=False; quit=False
    # group by file and apply accepted edits per file as we go (original applies each accepted before next prompt)
    for file_display,doc_text,matches in group_matches_by_file(all_matches):
        fs_path=matches[0].get('fs_path') if matches else None
        accepted_edits=[]
        for m in matches:
            if quit: break
            if m.get('replacement') is None: continue
            if accept_all:
                accepted_edits.append(m); continue
            # build single-edit diff content
            while True:
                new_text,_=apply_edits(doc_text, [(m['replacement_offsets'][0] if m.get('replacement_offsets') else m['node'].start, m['replacement_offsets'][1] if m.get('replacement_offsets') else m['node'].end, m['replacement'], m)])
                diff=make_diff(doc_text,new_text,color=False)
                title=''
                if m.get('rule') is not None:
                    title=f"{SEV_DISPLAY.get(m.get('severity'),m.get('severity'))}[{m['rule'].id}]: {m.get('message','')}\n"
                content=f"{file_display}\n{title}{diff}"
                ans=session.prompt(content,'rewrite')
                if ans=='y':
                    accepted_edits.append(m); break
                if ans=='n': break
                if ans=='a':
                    accept_all=True; accepted_edits.append(m); break
                if ans=='q':
                    quit=True; break
                if ans=='e':
                    edited=open_editor_for_text(m['replacement'])
                    # Editor file may end with newline added by editor; original likely trims trailing newline? Keep rstrip one trailing \n
                    if edited.endswith('\n'): edited=edited[:-1]
                    m['replacement']=edited; continue
            # end while
        # apply accepted for this file now
        if accepted_edits:
            new_text,applied=apply_edits(doc_text, build_edits_for_matches(accepted_edits))
            applied+=len(applied)
            if mode=='stdin':
                sys.stdout.write(new_text+"\n")
            elif fs_path:
                with open(fs_path,'w',encoding='utf-8',newline='') as f: f.write(new_text)
        if quit:
            # Warning lines (colored if tty)
            if sys.stdout.isatty():
                sys.stdout.write("\x1b[33mWarning:\x1b[0m \x1b[1mInteractive editing exited.\x1b[0m\n\x1b[34mHelp:\x1b[0m Your accepted edit has been saved.\n")
            else:
                sys.stdout.write("Warning: Interactive editing exited.\nHelp: Your accepted edit has been saved.\n")
            return applied
    if applied:
        # Original in tty flow prints Applied to stdout after leaving alt; in -U flows it was stderr. Interactive probe merged; put stdout if tty else stderr.
        if sys.stdout.isatty(): sys.stdout.write(f"Applied {applied} changes\n")
        else: eprint(f"Applied {applied} changes\n")
    return applied

def handle_interactive_view(all_matches, opts, color=False):
    session=Interactive()
    for m in all_matches:
        if m.get('rule') is not None:
            content=render_rich_diagnostic(m,color=False)
            # render_rich ends with blank line; in interactive prompt original rich content then Next... (it had blank? scan interactive pipe showed diagnostics then prompt after blank line? It printed both diagnostics before prompt for scan due buffering. We'll do per match.)
        else:
            # plain line
            node=m['node']; sl,sc=node.doc.line_col(node.start)
            content=f"{m['file']}:{sl+1}:{m['doc_text'].splitlines()[sl] if sl < len(m['doc_text'].splitlines()) else ''}\n"
        ans=session.prompt(content,'view')
        if ans=='q': break
        if ans=='e':
            # open file in editor
            import subprocess
            editor=os.environ.get('EDITOR') or 'vi'
            path=m.get('fs_path') or m['file']
            subprocess.call(f"{editor} {path}",shell=True)

# ---------- scan ----------
def get_scan_rules(opts, project):
    inline=opts.get('inline_rules') if 'inline_rules' in opts.present else None
    rule_file=opts.get('rule') if 'rule' in opts.present else None
    utils=[]
    global_utils={}
    if rule_file:
        rules=load_single_rule_file(rule_file, project if project.is_project else None)
        # if project exists, global utils from project util dirs may apply
        if project.is_project:
            try:
                _,util_configs,gu=load_rules_from_project(project)
                global_utils=gu
            except AppError:
                # if project rules contain duplicates etc, loading single rule still maybe loads util only - ignore for now
                pass
    elif inline is not None:
        rules=load_rule_configs_from_text(inline,'INLINE_RULES', project if project.is_project else None)
        if project.is_project:
            # load global util only
            try:
                _,util_configs,gu=load_rules_from_project(project); global_utils=gu
            except Exception:
                pass
    else:
        if not project.is_project:
            raise AppError(3, format_app_error("No ast-grep project configuration is found.","You need to create an ast-grep project for this command. Try `sg new` to create one.","https://ast-grep.github.io/guide/scan-project.html"))
        rules, util_configs, global_utils = load_rules_from_project(project)
    # filter
    filt=opts.get('filter') if 'filter' in opts.present else None
    if filt:
        try:
            rx=re.compile(filt)
        except re.error as e:
            raise AppError(8, f"Error: {e}\n")
        filtered=[r for r in rules if rx.search(r.id)]
        if not filtered:
            raise AppError(3, format_app_error(f"Rule not found: {filt}",f"Rule with id '{filt}' not found in project configuration. Please make sure it exists.","https://ast-grep.github.io/guide/tooling-overview.html#parse-code-from-stdin"))
        rules=filtered
    for rc in rules:
        if global_utils:
            rc.set_global_utils(global_utils)
            try:
                rc._matcher=None; rc.get_matcher()
            except RuleLoadError as e:
                raise rule_parse_error(rc.source_label,e.causes)
    return rules

def scan_command(opts):
    use_stdin=bool(opts.get('stdin'))
    # Project required unless rule/inline. Load project optionally first (if config explicitly specified errors handled); if rule/inline and no project, fine.
    has_rule_arg=('rule' in opts.present) or ('inline_rules' in opts.present)
    project=load_project_for(opts, required=False)
    if not has_rule_arg and not project.is_project:
        raise AppError(3, format_app_error("No ast-grep project configuration is found.","You need to create an ast-grep project for this command. Try `sg new` to create one.","https://ast-grep.github.io/guide/scan-project.html"))
    rules=get_scan_rules(opts, project)
    inspect=opts.get('inspect') or 'nothing'
    inspect_project_line(project,inspect)
    # effective rules after severity overrides & off
    eff_rules=[]
    skipped_rules=0
    for rc in rules:
        sev=effective_severity(rc,opts)
        if sev=='off':
            skipped_rules+=1
        else:
            eff_rules.append((rc,sev))
    if inspect=='entity':
        for rc,sev in eff_rules:
            eprint(f"sg: entity|rule|{rc.id}: finalSeverity={SEV_CAP.get(sev,sev)}\n")
    # stdin language determination: need a language. Original scan stdin with rules: if rules have only one lang? If multiple/no rules error like run?
    all_matches=[]; scanned=0; skipped=0; entities=[]
    max_results=opts.get('max_results')
    max_results=int(max_results) if max_results not in (None,'') else None
    if use_stdin:
        text=sys.stdin.read()
        # Determine language from rules: if exactly one distinct lang use it; if multiple, original maybe asks? Test later. Use all rules and try each rule's language on stdin separately? SourceDoc lang per rule can differ but file text same; evaluating per rule with its language requires parsing with that language individually. Simplify: group rules by lang, parse per lang.
        # If no rules empty.
        for rc,sev in eff_rules:
            doc=SourceDoc(text,rc.language)
            for node,env in evaluate_rule_on_doc(rc,doc):
                m=make_scan_match(rc,sev,node,env,'STDIN',text,doc,opts,project)
                all_matches.append(m)
                if max_results is not None and len(all_matches)>=max_results: break
            if max_results is not None and len(all_matches)>=max_results: break
    else:
        allowed=None
        if eff_rules:
            allowed=set(rc.language for rc,sev in eff_rules)
        stderr_errors=[]
        entries=collect_files(opts.positionals or ['.'], project, explicit_lang=None, follow=bool(opts.get('follow')), no_ignore=opts.get('no_ignore') or [], globs=opts.get('globs') or [], allowed_langs=allowed, stderr_list=stderr_errors)
        for msg in stderr_errors: eprint(msg)
        for ent in entries:
            try: text=read_source(ent.fs_path)
            except OSError: skipped+=1; continue
            if text is None: skipped+=1; continue
            scanned+=1
            doc=SourceDoc(text,ent.lang)
            applied_count=0
            for rc,sev in eff_rules:
                if rc.language!=ent.lang: continue
                path_for_glob=_path_for_rule_glob(ent,project)
                if not rule_applies_to_path(rc,path_for_glob): continue
                applied_count+=1
                for node,env in evaluate_rule_on_doc(rc,doc):
                    m=make_scan_match(rc,sev,node,env,ent.display,text,doc,opts,project)
                    m['fs_path']=ent.fs_path
                    all_matches.append(m)
                    if max_results is not None and len(all_matches)>=max_results: break
                if max_results is not None and len(all_matches)>=max_results: break
            entities.append((ent.display,ent.lang,applied_count))
            if max_results is not None and len(all_matches)>=max_results: break
    # sort by file then start then rule id for deterministic (except JSON might also use)
    # Keep grouped by initial file order then node start
    file_order={}
    for i,(f,_,_) in enumerate([(e[0],None,None) for e in entities]): file_order.setdefault(f,i)
    # all_matches already by file/rule; for text output we can sort stable by node start within same file
    all_matches_sorted=sorted(all_matches, key=lambda m:(m['file'], m['node'].start))
    if inspect=='entity' and not use_stdin:
        for f,lang,cnt in entities:
            eprint(f"sg: entity|file|{f}: language={lang},appliedRuleCount={cnt}\n")
    if inspect!='nothing':
        eprint(f"sg: summary|file: scannedFileCount={scanned if not use_stdin else 0},skippedFileCount={skipped if not use_stdin else 0}\n")
        eprint(f"sg: summary|rule: effectiveRuleCount={len(eff_rules)},skippedRuleCount={skipped_rules}\n")
    # output
    code=output_scan_matches(all_matches_sorted, opts, project, use_stdin, text if use_stdin else None)
    err_count=sum(1 for m in all_matches_sorted if m.get('severity')=='error')
    # In update-all mode, does error count still trigger? We'll keep as original maybe; output_scan_matches returns code based applied? For now if err_count and not update...
    if err_count:
        eprint(f"Error: {err_count} error(s) found in code.\nHelp: Scan succeeded and found error level diagnostics in the codebase.\n\n")
        return 1
    return code

def _path_for_rule_glob(ent, project):
    if project and project.is_project and project.project_dir:
        try:
            rel=os.path.relpath(os.path.abspath(ent.fs_path), project.project_dir)
            if not rel.startswith('..'): return rel.replace(os.sep,'/')
        except: pass
    return ent.display

def make_scan_match(rc, sev, node, env, file_display, text, doc, opts, project):
    # fix generation
    from rules import Ctx, generate_fix
    ctx=Ctx(rc,doc)
    fix_res=generate_fix(rc,env,node,ctx)
    replacement=None; repl_off=None; fix_configs=None
    if fix_res:
        replacement, repl_off, fix_configs = fix_res
    message=substitute_template(rc.message,env,node,apply_indent=False) if rc.message else ''
    labels=get_labels_for_rule(rc,node,env)
    m=make_match_dict(node,env,file_display,text,rc.language,replacement=replacement,repl_offsets=repl_off,rule=rc,severity=sev,message=message,labels=labels,include_metadata=bool(opts.get('include_metadata')),fix_configs=fix_configs)
    return m

def output_scan_matches(matches, opts, project, use_stdin=False, stdin_text=None):
    json_style=opts.get('json') if 'json' in opts.present else None
    fmt=opts.get('format') if 'format' in opts.present else None
    files_with=bool(opts.get('files_with_matches'))
    update_all=bool(opts.get('update_all')); interactive=bool(opts.get('interactive'))
    color_enabled=should_color(opts.get('color','auto'), sys.stdout.isatty())
    report=opts.get('report_style') or 'rich'
    def json_ready(ms):
        out=[]
        for m in ms:
            mm=dict(m)
            if mm.get('replacement') is not None:
                mm['replacement_offsets']=rewrite_offsets_json(m)
            out.append(mm)
        return out
    if json_style:
        # if update_all also set, original may apply before json? We'll apply edits too if update_all and not stdin.
        if update_all and not use_stdin:
            applied=apply_rewrites_to_files(matches)
            if applied: eprint(f"Applied {applied} changes\n")
        sys.stdout.write(dump_json_matches(json_ready(matches),json_style))
        return 0
    if fmt=='sarif':
        sys.stdout.write(dump_sarif(matches)+'\n'); return 0
    if fmt=='github':
        for m in matches:
            sev=m.get('severity')
            level={'info':'notice','warning':'warning','error':'error'}.get(sev)
            if not level: continue
            node=m['node']; sl,sc=node.doc.line_col(node.start); el,ec=node.doc.line_col(node.end)
            sys.stdout.write(f"::{level} file={m['file']},line={sl+1},endLine={el+1},title={m['rule'].id}::{m.get('message','')}\n")
        return 0
    if files_with:
        seen=[]
        for m in matches:
            if m['file'] not in seen: seen.append(m['file'])
        for f in seen: sys.stdout.write(f+'\n')
        return 0
    if interactive:
        # Separate matches with fix (rewrite prompt) and without (view prompt) in order.
        # Original scan interactive groups maybe by match type. We'll handle sequentially: rewrite matches individually using handle_interactive_rewrites for those; diagnostics before.
        # Simplification: if any fix matches, run interactive rewrites for them; view for rest first in order encountered.
        for m in matches:
            if m.get('replacement') is not None:
                handle_interactive_rewrites([m],opts,color_enabled,mode='run')
            else:
                handle_interactive_view([m],opts,color_enabled)
        return 0
    if update_all:
        if use_stdin:
            if matches:
                new_text,applied=apply_edits(stdin_text, build_edits_for_matches(matches))
                sys.stdout.write(new_text+"\n"); eprint(f"Applied {len(applied)} changes\n")
            return 0
        applied=apply_rewrites_to_files(matches)
        if applied: eprint(f"Applied {applied} changes\n")
        return 0
    # normal diagnostic / diff per match
    for m in matches:
        rc=m['rule']; sev=m.get('severity',rc.severity); sev_disp=SEV_DISPLAY.get(sev,sev); message=m.get('message','')
        node=m['node']; sl,sc=node.doc.line_col(node.start)
        # location for medium/short with labels: original uses match node location or primary label? Short in labels probe not checked; rich location used primary label. For medium/short likely file location printed is primary label too? We'll use primary label if labels configured.
        primary_node=node
        labs=m.get('labels') or []
        prim=next((l for l in labs if l.get('style')=='primary'),None)
        if rc.labels and prim is not None:
            primary_node=prim['node']; sl,sc=primary_node.doc.line_col(primary_node.start)
        if m.get('replacement') is not None:
            if report=='rich':
                if color_enabled:
                    sys.stdout.write(f"\x1b[3;36m{m['file']}\x1b[0m\n"); sys.stdout.write(sev_header_colored(sev,rc.id,message)+'\n')
                else:
                    sys.stdout.write(f"{m['file']}\n{sev_disp}[{rc.id}]: {message}\n")
                new_text,_=apply_edits(m['doc_text'], build_edits_for_matches([m]))
                sys.stdout.write(make_diff(m['doc_text'],new_text,color=color_enabled))
                if rc.note:
                    if color_enabled: sys.stdout.write("\x1b[3mNote:\x1b[0m\n")
                    else: sys.stdout.write("Note:\n")
                    sys.stdout.write(str(rc.note)+"\n\n")
            elif report=='medium':
                hdr=sev_header_colored(sev,rc.id,message) if color_enabled else f"{sev_disp}[{rc.id}]: {message}"
                sys.stdout.write(f"{m['file']}:{sl+1}:{sc+1}: {hdr}\n")
                if rc.note:
                    sys.stdout.write("Note:\n"+str(rc.note)+"\n\n")
            else:
                hdr=sev_header_colored(sev,rc.id,message) if color_enabled else f"{sev_disp}[{rc.id}]: {message}"
                sys.stdout.write(f"{m['file']}:{sl+1}:{sc+1}: {hdr}\n")
        else:
            if report=='rich':
                sys.stdout.write(render_rich_diagnostic(m,color=color_enabled))
            elif report=='medium':
                if color_enabled:
                    hdr_full=f"\x1b[0m\x1b[1m\x1b[38;5;{{'hint':'14','info':'10','warning':'11','error':'9'}.get(sev,'11')}m{sev_disp}[{rc.id}]\x1b[0m\x1b[1m: {message}\x1b[0m"
                    # fix format string above (it contains braces) -> construct directly
                    sevcolor={'hint':'14','info':'10','warning':'11','error':'9'}.get(sev,'11')
                    hdr_full=f"\x1b[0m\x1b[1m\x1b[38;5;{sevcolor}m{sev_disp}[{rc.id}]\x1b[0m\x1b[1m: {message}\x1b[0m"
                    sys.stdout.write(f"{m['file']}:{sl+1}:{sc+1}: {hdr_full}\n")
                else:
                    sys.stdout.write(f"{m['file']}:{sl+1}:{sc+1}: {sev_disp}[{rc.id}]: {message}\n")
                if rc.note:
                    note_lines=str(rc.note).split('\n')
                    sys.stdout.write(f" = {note_lines[0]}\n")
                    for nl in note_lines[1:]: sys.stdout.write(f"   {nl}\n")
            else:
                if color_enabled:
                    sevcolor={'hint':'14','info':'10','warning':'11','error':'9'}.get(sev,'11')
                    hdr_full=f"\x1b[0m\x1b[1m\x1b[38;5;{sevcolor}m{sev_disp}[{rc.id}]\x1b[0m\x1b[1m: {message}\x1b[0m"
                    sys.stdout.write(f"{m['file']}:{sl+1}:{sc+1}: {hdr_full}\n")
                else:
                    sys.stdout.write(f"{m['file']}:{sl+1}:{sc+1}: {sev_disp}[{rc.id}]: {message}\n")
    return 0

def dump_sarif(matches):
    results=[]
    for m in matches:
        node=m['node']; sl,sc=node.doc.line_col(node.start); el,ec=node.doc.line_col(node.end)
        level={'hint':'note','info':'note','warning':'warning','error':'error'}.get(m.get('severity'),'note')
        region={"byteLength": node.doc.byte_offset(node.end)-node.doc.byte_offset(node.start), "byteOffset": node.doc.byte_offset(node.start), "endColumn": ec+1, "endLine": el+1, "snippet":{"text":node.text()}, "startColumn": sc+1, "startLine": sl+1}
        results.append({"level":level,"locations":[{"physicalLocation":{"artifactLocation":{"uri":m['file']},"region":region}}],"message":{"text":m.get('message','')},"ruleId":m['rule'].id})
    obj={"runs":[{"results":results,"tool":{"driver":{"name":"ast-grep"}}}],"version":"0.42.1"}
    return json.dumps(obj,indent=2,sort_keys=True,ensure_ascii=False)

# ---------- test command ----------
def test_command(opts):
    project=load_project_for(opts, required=True)
    # load rules (may raise)
    rules,_,_ = load_rules_from_project(project)
    include_off=bool(opts.get('include_off'))
    rule_by_id={r.id:r for r in rules if include_off or r.severity!='off'}
    test_dir_arg=opts.get('test_dir')
    snapshot_dirname=opts.get('snapshot_dir') or '__snapshots__'
    test_configs=[]
    if test_dir_arg:
        test_configs=[{'testDir':test_dir_arg,'snapshotDir':snapshot_dirname}]
    else:
        test_configs=project.test_configs()
    # if no test configs? original: maybe no tests. We'll handle by zero tests.
    filter_rx=None
    if opts.get('filter'):
        try: filter_rx=re.compile(opts.get('filter'))
        except re.error as e: raise AppError(1,f"Error: {e}\n")
    update_all=bool(opts.get('update_all')); skip_snap=bool(opts.get('skip_snapshot_tests')); interactive=bool(opts.get('interactive'))
    cases=[]  # each test case file yields one "test" per rule id? Running N tests = number of test YAML files (?) In probe one file -> Running 1 tests, results counts 1 passed even with two cases + snapshot update. So test unit = rule test file/id.
    for cfg in test_configs:
        if not isinstance(cfg,dict): continue
        td=cfg.get('testDir')
        if not td: continue
        abs_td=td if os.path.isabs(td) else os.path.join(project.project_dir,td)
        snap_dirname_cfg=cfg.get('snapshotDir') or snapshot_dirname
        snap_dir=os.path.join(abs_td,snap_dirname_cfg) if not os.path.isabs(snap_dirname_cfg) else snap_dirname_cfg
        if not os.path.isdir(abs_td): continue
        for root,dirs,files in os.walk(abs_td):
            # don't descend snapshots dir
            dirs[:]=[d for d in dirs if os.path.join(root,d)!=snap_dir]
            for fn in sorted(files):
                if fn.endswith('.yml') or fn.endswith('.yaml'):
                    cases.append((os.path.join(root,fn),abs_td,snap_dir))
    # Filter by rule id from file content later; parse here
    parsed_cases=[]
    for path,td,snap_dir in cases:
        try:
            text=open(path,encoding='utf-8').read(); data=parse_yaml(text)
        except Exception as e:
            data=None
        if not isinstance(data,dict): continue
        rid=str(data.get('id') or '')
        if filter_rx and not filter_rx.search(rid): continue
        parsed_cases.append((path,td,snap_dir,data))
    n=len(parsed_cases)
    color_enabled=should_color(opts.get('color','auto'),sys.stdout.isatty())
    sys.stdout.write(f"Running {n} tests\n\n")
    details=[]; passed=0; failed=0
    # We'll run each and collect detail output in original order.
    for path,td,snap_dir,data in parsed_cases:
        rid=str(data.get('id') or '')
        rc=rule_by_id.get(rid)
        valid=data.get('valid') or []; invalid=data.get('invalid') or []
        if not isinstance(valid,list): valid=[valid]
        if not isinstance(invalid,list): invalid=[invalid]
        chars=[]; case_failed=False; snapshots_new={}; snapshot_file=os.path.join(snap_dir,f"{rid}-snapshot.yml")
        existing_snaps={}
        if os.path.isfile(snapshot_file):
            try:
                sdata=parse_yaml(open(snapshot_file,encoding='utf-8').read())
                if isinstance(sdata,dict) and isinstance(sdata.get('snapshots'),dict): existing_snaps=sdata['snapshots']
            except Exception: existing_snaps={}
        changed=False
        # valid cases: should have no matches
        for code in valid:
            code_s=str(code)
            if rc is None:
                chars.append('?'); case_failed=True; details.append(f"[Error] Rule {rid} not found.\nFor Code:\n  {code_s}\n"); continue
            doc=SourceDoc(code_s,rc.language)
            matches=evaluate_rule_on_doc(rc,doc)
            if matches:
                case_failed=True; chars.append('X')
                first=matches[0]
                labels=_snap_labels(rc,first[0],first[1],code_s)
                details.append(f"[Wrong] Expected no matches for {rid}, but found one.\nGenerated Snapshot:\n{_format_snap(labels)}\nFor Code:\n  {code_s}\n")
            else:
                chars.append('.')
        for code in invalid:
            code_s=str(code)
            if rc is None:
                chars.append('?'); case_failed=True; continue
            doc=SourceDoc(code_s,rc.language)
            matches=evaluate_rule_on_doc(rc,doc)
            if not matches:
                case_failed=True; chars.append('X')
                details.append(f"[Wrong] Expected {rid} to match, but found no matches.\nFor Code:\n  {code_s}\n")
                continue
            if skip_snap:
                chars.append('.'); continue
            # Generate snapshot labels for first match (?) Original snapshots maps source code string to labels list of *all matches? If multiple matches multiple labels entries likely from all diagnostics.
            labels=[]
            for node,env in matches:
                labs=get_labels_for_rule(rc,node,env)
                for lab in labs:
                    labels.append({'source':lab['node'].text(),'style':lab.get('style','primary'),'start':lab['node'].start,'end':lab['node'].end} | ({'message':lab['message']} if lab.get('message') else {}))
                    # Order in original snapshot labels entries: source, style, start, end (and message maybe location?) We'll construct dict ordered in dumping manually later.
            snapshots_new[code_s]={'labels':labels}
            if code_s not in existing_snaps:
                if update_all:
                    chars.append('U'); changed=True
                    details.append(f"[Updated] Rule {rid}'s snapshot baseline has been updated.\n\n  {code_s}\n")
                elif interactive:
                    # prompt logic for test interactive later
                    ans=_test_interactive_prompt(rid,code_s,labels,None)
                    if ans=='u': chars.append('U'); changed=True
                    else: chars.append('W'); case_failed=True
                else:
                    chars.append('W'); case_failed=True
                    details.append(f"[Wrong] No {rid} baseline found.\nGenerated Snapshot:\n{_format_snap(labels)}\nFor Code:\n  {code_s}\n")
            else:
                if existing_snaps.get(code_s)=={'labels':labels} or _snap_equal(existing_snaps.get(code_s),labels):
                    chars.append('.')
                else:
                    if update_all:
                        chars.append('U'); changed=True
                        details.append(f"[Updated] Rule {rid}'s snapshot baseline has been updated.\n\n  {code_s}\n")
                    elif interactive:
                        ans=_test_interactive_prompt(rid,code_s,labels,existing_snaps.get(code_s))
                        if ans=='u': chars.append('U'); changed=True
                        else: chars.append('W'); case_failed=True
                    else:
                        chars.append('W'); case_failed=True
                        details.append(f"[Wrong] Snapshot for {rid} does not match.\nGenerated Snapshot:\n{_format_snap(labels)}\nFor Code:\n  {code_s}\n")
        # unused snapshots? ignore
        if changed and (update_all or interactive):
            os.makedirs(snap_dir,exist_ok=True)
            merged=dict(existing_snaps); merged.update(snapshots_new)
            snap_obj={'id':rid,'snapshots':merged}
            with open(snapshot_file,'w',encoding='utf-8') as f: f.write(_dump_snapshot_yaml(snap_obj))
            if 'W' not in chars and 'X' not in chars: case_failed=False
        status='FAIL' if case_failed else 'PASS'
        if case_failed: failed+=1
        else: passed+=1
        # store line to print after details heading (original prints details then PASS/FAIL lines per case interleaved? Output format: "Running\n\n--- Case Details ---\n[Wrong]...\n\nFAIL ..." For multiple cases likely details for each before its line)
        # We print later per case using details collected so far; need track.
        parsed_cases_line=f"{status} {rid}  {''.join(chars)}"
        # attach to a list in order with details segment
        # details variable is global accumulated; use per-case capture by slicing: simplest store tuple at end in a separate list
        # We'll abuse data dict storage
        data['_line']=parsed_cases_line
        data['_details'] = list(details)  # cumulative snapshot at this point is wrong if multiple; but we reset details after each case below
        # reset for next case: keep stored in data, clear global
        details=[]
    sys.stdout.write("----------- Case Details -----------\n")
    for path,td,snap_dir,data in parsed_cases:
        for d in data.get('_details',[]):
            sys.stdout.write(d if d.endswith('\n') else d+'\n')
            if not d.endswith('\n\n'): sys.stdout.write('\n')
        sys.stdout.write(data.get('_line','')+'\n')
    sys.stdout.write('\n')
    if failed:
        eprint(f"Error: test failed. {passed} passed; {failed} failed;\nHelp: Test failed due to mismatching snapshots. Run with `--update-all` to update all snapshots, or `--interactive` to update selectively.\nSee also: https://ast-grep.github.io/guide/test-rule.html\n\n")
        return 4
    else:
        sys.stdout.write(f"test result: ok. {passed} passed; {failed} failed;\n")
        return 0

def _snap_labels(rc,node,env,code):
    labs=get_labels_for_rule(rc,node,env)
    return [{'source':l['node'].text(),'style':l.get('style','primary'),'start':l['node'].start,'end':l['node'].end} for l in labs]
def _format_snap(labels):
    # Format like YAML snippet indented two spaces under Generated Snapshot:
    # "  labels:\n  - source: ...\n    style: ...\n    start: ...\n    end: ..."
    lines=["  labels:"]
    for lab in labels:
        lines.append(f"  - source: {lab['source']}")
        if lab.get('message'): lines.append(f"    message: {lab['message']}")
        lines.append(f"    style: {lab['style']}")
        lines.append(f"    start: {lab['start']}")
        lines.append(f"    end: {lab['end']}")
    return '\n'.join(lines)
def _snap_equal(existing, labels):
    if not isinstance(existing,dict): return False
    el=existing.get('labels')
    if not isinstance(el,list) or len(el)!=len(labels): return False
    for a,b in zip(el,labels):
        if not isinstance(a,dict): return False
        # snapshot label entries may include message before style etc
        for k in ('source','style','start','end'):
            if a.get(k)!=b.get(k): return False
    return True
def _dump_snapshot_yaml(obj):
    # Use our YAML emitter but ensure label dict order source/style/start/end (dicts inserted that way mostly)
    return dump_yaml(obj)
def _test_interactive_prompt(rid,code,labels,existing):
    # Prompt format unknown; implemented later after probing. For now treat as not updated.
    return 'w'

