def new_command(opts, entity=None, name=None):
    yes=bool(opts.get('yes')); lang_raw=opts.get('lang'); config_arg=opts.get('config')
    # entity None means interactive or --yes error
    if entity is None:
        if yes:
            raise AppError(22, format_app_error("Insufficient command line argument provided to use `--yes` option.","You need to provide `entity` in command line to use non-interactive `new`.",None))
        # check project existence: if no project and no entity, original when -y creates project, without -y in non-tty it errors TTY before? In probes: empty dir `new -y` -> creates project with prefix message. Empty dir `new` (no tty) -> likely prompts to create project and fails TTY. Project dir `new` -> TTY error.
        proj=find_project(config_arg,required=False)
        if not sys.stdin.isatty():
            raise AppError(1, "Error: The input device is not a TTY\n")
        # Interactive new via prompts not implemented in this stub path - fallthrough TTY prompt implementation in new_interactive
        return new_interactive(opts, proj)
    if entity=='project':
