                raise AppError(22, format_app_error("Insufficient command line argument provided to use `--yes` option.","You need to provide `lang` in command line to use non-interactive `new`.",None))
        else:
            if not sys.stdin.isatty():
                # If name/lang provided but not yes, original might still need interactive selection for rule dir if multiple; if one, maybe proceeds? Probe later. For a single rule dir and provided name/lang, we can proceed non-interactively.
