def _create_project(custom_config=None, quiet_prefix=None):
    cwd=os.getcwd()
    if custom_config:
        config_path=os.path.abspath(custom_config); base=os.path.dirname(config_path)
    else:
        config_path=os.path.join(cwd,'sgconfig.yml'); base=cwd
    # Messages: caller for `new` no entity no project with -y needs prefix "No sgconfig.yml found. Creating..."
    if quiet_prefix: sys.stdout.write(quiet_prefix)
    sys.stdout.write("Creating a new ast-grep project...\n")
    rules_dir=os.path.join(base,'rules'); tests_dir=os.path.join(base,'rule-tests'); utils_dir=os.path.join(base,'utils')
    for d in (rules_dir,tests_dir,utils_dir): os.makedirs(d,exist_ok=True)
    for d in (rules_dir,tests_dir,utils_dir):
        keep=os.path.join(d,'.gitkeep')
        if not os.path.exists(keep): open(keep,'w').close()
    content=f"ruleDirs:\n- {rules_dir}\ntestConfigs:\n- testDir: {tests_dir}\nutilDirs:\n- {utils_dir}\n"
    with open(config_path,'w',encoding='utf-8') as f: f.write(content)
    sys.stdout.write("Your new ast-grep project has been created!\n")
    return 0

