def main(argv=None):
    global BINNAME
    if argv is None: argv=sys.argv
    prog=argv[0] if argv else 'executable'
    BINNAME=os.path.basename(prog) or 'executable'
    cli.set_bin(BINNAME)
    args=list(argv[1:])
    try:
        return dispatch(args)
    except ClapExit as e:
        if e.out: sys.stdout.write(e.out)
        if e.err: eprint(e.err)
        return e.code
    except AppError as e:
        eprint(e.text); return e.code
    except BrokenPipeError:
        # Match original broken pipe for --json | head? It printed "Error: Broken pipe (os error 32)" to stderr in one scan probe (head). Python exit handling later.
        try: eprint("Error: Broken pipe (os error 32)\n")
        except: pass
        return 1

def _has_pattern_flag(args):
    for a in args:
        if a in ('-p','--pattern') or a.startswith('--pattern=') or a.startswith('-p='):
            return True
    return False

def dispatch(args):
    BIN=cli.BIN
    if not args:
        # print short root help to stderr exit2
        eprint(help_text('root','short')); return 2
    # version at top if first token -V/--version and no pattern flag (pattern flag makes it defrun unexpected)
    if not _has_pattern_flag(args):
        if args and args[0] in ('-V','--version'):
            sys.stdout.write(VERSION+'\n'); return 0
    # default run detection
    if args and args[0].startswith('-') and _has_pattern_flag(args):
        spec=SPECS['defrun']
        opts=parse_args(spec,args)
        return run_command(opts, default_mode=True)
    # help subcommand
    if args[0]=='help':
        return help_dispatch(args[1:])
    # top-level options before subcommand: only -c/--config, -h/--help, -V/--version
    config_arg=None; idx=0; top_present=[]
    while idx<len(args) and args[idx].startswith('-'):
        a=args[idx]
        if a in ('-h','--help'):
            sys.stdout.write(help_text('root','long' if a=='--help' else 'short')); return 0
        if a in ('-V','--version'):
            sys.stdout.write(VERSION+'\n'); return 0
        if a in ('-c','--config'):
            if idx+1>=len(args):
                raise ClapExit(2,'',f"error: a value is required for '--config <CONFIG_FILE>' but none was supplied\n\nFor more information, try '--help'.\n")
            config_arg=args[idx+1]; top_present.append('config'); idx+=2; continue
        if a.startswith('--config='):
            config_arg=a.split('=',1)[1]; idx+=1; continue
        if a.startswith('-c') and len(a)>2:
            cfg=a[2:].lstrip('='); config_arg=cfg; idx+=1; continue
        # unknown top-level
        spec=SPECS['root']
        # Use parser just to generate consistent error: parse a fake call
        # But it may consume subcommand as positional, so directly format.
        body=a.lstrip('-').split('=',1)[0]
        if a.startswith('--'):
            cand=similar(body,['config','help','version'])
            if cand:
                usage=f"{BIN} --{cand}" + (" <CONFIG_FILE>" if cand=='config' else "") + " <COMMAND>"
                raise ClapExit(2,'',format_error(f"unexpected argument '{a.split('=',1)[0]}' found",spec,tip=f"a similar argument exists: '--{cand}'",usage=usage))
            raise ClapExit(2,'',format_error(f"unexpected argument '{a.split('=',1)[0]}' found",spec,usage=spec.canonical_usage()))
        else:
            raise ClapExit(2,'',format_error(f"unexpected argument '-{a[1]}' found",spec,usage=spec.canonical_usage()))
    if idx>=len(args):
        # e.g. -c x only
        raise ClapExit(2,'',f"error: '{BIN}' requires a subcommand but one was not provided\n  [subcommands: run, scan, test, new, lsp, completions, help]\n\nUsage: {BIN} [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.\n")
    cmd=args[idx]; rest=args[idx+1:]
    if config_arg is not None:
        rest=['-c',config_arg]+rest  # inject into subcommand parser (all subcommands have -c except note new subcommands too, lsp etc)
    if cmd=='run':
        opts=parse_args(SPECS['run'],rest); return run_command(opts)
    if cmd=='scan':
        opts=parse_args(SPECS['scan'],rest); return scan_command(opts)
    if cmd=='test':
        opts=parse_args(SPECS['test'],rest,allow_positional=False); return test_command(opts)
    if cmd=='lsp':
        opts=parse_args(SPECS['lsp'],rest,allow_positional=False)
        from lsp import run_lsp
        return run_lsp(opts)
    if cmd=='completions':
        # validate shell possible values before generic
        opts=parse_args(SPECS['completions'],rest,max_positional=1)
        if opts.positionals and opts.positionals[0] not in ('bash','elvish','fish','powershell','zsh'):
            raise ClapExit(2,'',f"error: invalid value '{opts.positionals[0]}' for '[SHELL]'\n  [possible values: bash, elvish, fish, powershell, zsh]\n\nFor more information, try '--help'.\n")
        return completions_command(opts)
    if cmd=='new':
        return new_dispatch(rest)
    # unrecognized subcommand
    spec=SPECS['root']
    cand=similar(cmd, list(spec.subcommands))
    tip=f"a similar subcommand exists: '{cand}'" if cand else None
    raise ClapExit(2,'',format_error(f"unrecognized subcommand '{cmd}'",spec,tip=tip,usage=spec.canonical_usage()))

def help_dispatch(args):
    if not args:
        sys.stdout.write(help_text('root','long')); return 0
    # help help
    if args==['help']:
        from help_data import HELP_DATA; sys.stdout.write(HELP_DATA['help_help'].replace('{BIN}',cli.BIN)); return 0
    cmd=args[0]
