from engine import SourceDoc, substitute_template

SEV_LSP={'error':1,'warning':2,'info':3,'hint':4}

def uri_to_path(uri):
    try:
        p=urlparse(uri)
        if p.scheme=='file':
            return unquote(p.path)
    except Exception: pass
    return uri

def pos_dict(line,ch):
    return {"character":ch,"line":line}
def range_dict(doc,start,end):
    sl,sc=doc.line_col(start); el,ec=doc.line_col(end)
    return {"end":pos_dict(el,ec),"start":pos_dict(sl,sc)}

def labels_for(rc,node,env):
    cfg=rc.labels if isinstance(rc.labels,dict) else {}
    if not cfg:
        labs=[{'node':node,'style':'primary','message':None}]
        for sn in env.multi.get('secondary',[]): labs.append({'node':sn,'style':'secondary','message':None})
        return labs
    labs=[]
    for var,c in cfg.items():
        if not isinstance(c,dict): continue
        if var in env.single: labs.append({'node':env.single[var],'style':c.get('style','primary'),'message':c.get('message')})
    return labs or [{'node':node,'style':'primary','message':None}]

