        self.project=find_project(opts.get('config'),required=True)
        self.rules=[]; self.docs={}; self.matches={}; self.next_id=0; self.pending={}; self.shutdown=False
        self.inp=sys.stdin.buffer; self.out=sys.stdout.buffer
    def send_raw(self,obj):
        data=json.dumps(obj,separators=(',',':'),ensure_ascii=False).encode()
        self.out.write(b'Content-Length: '+str(len(data)).encode()+b'\r\n\r\n'+data); self.out.flush()
    def send_result(self,mid,result):
        self.send_raw({"jsonrpc":"2.0","result":result,"id":mid})
    def send_error(self,mid,code,message):
        self.send_raw({"jsonrpc":"2.0","error":{"code":code,"message":message},"id":mid})
    def log(self,message,typ=3):
        self.send_raw({"jsonrpc":"2.0","method":"window/logMessage","params":{"message":message,"type":typ}})
    def read_msg(self):
        headers=b''
        while not headers.endswith(b'\r\n\r\n'):
            ch=self.inp.read(1)
            if not ch: return None
            headers+=ch
        length=0
        for part in headers.decode(errors='ignore').split('\r\n'):
            if ':' in part:
                k,v=part.split(':',1)
                if k.strip().lower()=='content-length': length=int(v.strip())
        body=self.inp.read(length) if length else b''
        try: return json.loads(body.decode('utf-8'))
        except Exception: return {}
    def reload_rules(self,cli_logic=True,log_start=True):
        if log_start: self.log("Starting rule reload...",3)
        try:
            # Re-find project to pick config changes
            self.project=find_project(self.opts.get('config'),required=True)
            rules,_,_=load_rules_from_project(self.project)
            self.rules=rules
            self.log("Rules reloaded successfully using CLI logic" if cli_logic else "Rules reloaded successfully",3)
            return True
        except Exception as e:
            text=getattr(e,'text',str(e))
            self.log(f"Failed to reload rules: {text}",1)
            return False
    def compute_matches(self,uri):
        info=self.docs.get(uri)
        if not info: return []
        path=uri_to_path(uri)
        lang=info.get('lang') or lang_for_file(path,path,self.project)
        if not lang: 
            self.matches[uri]=[]; return []
        doc=SourceDoc(info['text'],lang)
        out=[]
        for rc in self.rules:
            if rc.severity=='off' or rc.language!=lang: continue
            if self.project and self.project.project_dir:
                try: rel=os.path.relpath(os.path.abspath(path),self.project.project_dir).replace(os.sep,'/')
                except: rel=path
            else: rel=path
            if not rule_applies_to_path(rc,rel): continue
            for node,env in evaluate_rule_on_doc(rc,doc):
                labs=labels_for(rc,node,env)
                primary=next((l for l in labs if l.get('style')=='primary'),labs[0])
                diag_range=range_dict(doc,primary['node'].start,primary['node'].end)
                message=substitute_template(rc.message,env,node,apply_indent=False) if rc.message else ''
                diag={"code":rc.id,"message":message,"range":diag_range,"severity":SEV_LSP.get(rc.severity,4),"source":"ast-grep"}
                out.append({'rc':rc,'node':node,'env':env,'doc':doc,'diag':diag,'labels':labs,'primary':primary})
        self.matches[uri]=out
        return out
    def publish(self,uri):
        matches=self.compute_matches(uri); info=self.docs.get(uri,{})
        self.send_raw({"jsonrpc":"2.0","method":"textDocument/publishDiagnostics","params":{"diagnostics":[m['diag'] for m in matches],"uri":uri,"version":info.get('version')}})
    def fixes_for_match(self,m):
        rc=m['rc']; env=m['env']; node=m['node']; doc=m['doc']; ctx=Ctx(rc,doc); out=[]
        for cfg in rc.fix_configs():
            template=cfg.get('template') if isinstance(cfg,dict) else None
            if template is None: continue
            repl=substitute_template(str(template),env,node,apply_indent=True)
            start=node.start; end=env.effective_end if getattr(env,'effective_end',None) is not None else node.end
            if isinstance(cfg,dict):
                if cfg.get('expandStart'):
                    st=expand_range(node,cfg['expandStart'],'start',rc,ctx)
                    if st is not None: start=st
                if cfg.get('expandEnd'):
                    en=expand_range(node,cfg['expandEnd'],'end',rc,ctx)
                    if en is not None: end=en
            title=cfg.get('title') if isinstance(cfg,dict) else None
            out.append({'newText':repl,'range':range_dict(doc,start,end),'title':title})
        return out
    def lang_from_id(self,language_id,uri):
        path=uri_to_path(uri)
        m={'javascript':'JavaScript','javascriptreact':'JavaScript','typescript':'TypeScript','typescriptreact':'Tsx','python':'Python','rust':'Rust','go':'Go','java':'Java','c':'C','cpp':'Cpp','csharp':'CSharp','css':'Css','html':'Html','json':'Json','jsonc':'Json','yaml':'Yaml','ruby':'Ruby','php':'Php','swift':'Swift','kotlin':'Kotlin','scala':'Scala','shellscript':'Bash','bash':'Bash','lua':'Lua','dart':'Dart','elixir':'Elixir','haskell':'Haskell','solidity':'Solidity','terraform':'Hcl','nix':'Nix'}
        if language_id and language_id.lower() in m: return m[language_id.lower()]
        return lang_for_file(path,path,self.project)
    def run(self):
        while True:
            msg=self.read_msg()
            if msg is None: break
            if not isinstance(msg,dict): continue
            method=msg.get('method'); mid=msg.get('id'); params=msg.get('params') or {}
            # response to server request
            if method is None:
                if mid in self.pending:
                    kind,orig_id=self.pending.pop(mid)
                    if kind=='execute':
                        self.send_result(orig_id,None)
                continue
            if method=='initialize':
                result={"capabilities":{"codeActionProvider":True,"executeCommandProvider":{"commands":["ast-grep.applyAllFixes"]},"hoverProvider":True,"textDocumentSync":1},"serverInfo":{"name":"ast-grep language server"}}
                self.send_result(mid,result)
            elif method=='initialized':
                self.log("server initialized!",3)
                self.reload_rules(cli_logic=True,log_start=True)
                reg_id=self.next_id; self.next_id+=1
                self.send_raw({"jsonrpc":"2.0","method":"client/registerCapability","params":{"registrations":[{"id":"ast-grep-config-watcher","method":"workspace/didChangeWatchedFiles","registerOptions":{"watchers":[{"globPattern":"**/*.{yml,yaml}","kind":7}]}}]},"id":reg_id})
            elif method=='textDocument/didOpen':
                td=params.get('textDocument') or {}; uri=td.get('uri')
                self.docs[uri]={'text':td.get('text',''),'version':td.get('version'),'languageId':td.get('languageId'),'lang':self.lang_from_id(td.get('languageId'),uri)}
                self.log("file opened!",3); self.log("Parsing doc.",4); self.log("Publishing init diagnostics.",4); self.publish(uri)
            elif method=='textDocument/didChange':
                td=params.get('textDocument') or {}; uri=td.get('uri')
                changes=params.get('contentChanges') or []
                if uri in self.docs and changes:
                    # Full sync: last change text is whole doc. If range present, our simple full replace may be wrong, but capability is Full.
                    txt=changes[-1].get('text')
                    if txt is not None: self.docs[uri]['text']=txt
                    self.docs[uri]['version']=td.get('version')
                self.log("Parsing changed doc.",4); self.log("Publishing diagnostics.",4)
                # compute/store but do not publish until save (matches observed)
                self.compute_matches(uri)
            elif method=='textDocument/didSave':
                td=params.get('textDocument') or {}; uri=td.get('uri')
                if params.get('text') is not None and uri in self.docs: self.docs[uri]['text']=params['text']
                self.publish(uri); self.log("file saved!",3)
            elif method=='textDocument/didClose':
                td=params.get('textDocument') or {}; uri=td.get('uri')
                self.log("file closed!",3)
                self.docs.pop(uri,None); self.matches.pop(uri,None)
            elif method=='workspace/didChangeWatchedFiles':
                self.log("Configuration files changed, reloading rules...",3)
                self.reload_rules(cli_logic=True,log_start=True)
                for uri in list(self.docs.keys()): self.publish(uri)
            elif method=='textDocument/hover':
                self.log("Get Hover Notes",4)
                uri=(params.get('textDocument') or {}).get('uri'); pos=params.get('position') or {}
                result=None; matches=self.matches.get(uri) or self.compute_matches(uri)
                for m in matches:
                    if not m['rc'].note: continue
                    node=m['primary']['node']; doc=m['doc']; sl,sc=doc.line_col(node.start); el,ec=doc.line_col(node.end)
                    line=pos.get('line'); ch=pos.get('character')
                    if line is None: continue
                    inside=(sl<line or (sl==line and sc<=ch)) and (line<el or (line==el and ch<=ec))
                    if inside:
                        result={"contents":{"kind":"markdown","value":m['rc'].note},"range":range_dict(doc,node.start,node.end)}; break
                self.send_result(mid,result)
            elif method=='textDocument/codeAction':
                uri=(params.get('textDocument') or {}).get('uri'); context=params.get('context') or {}; diags=context.get('diagnostics') or []
                matches=self.matches.get(uri) or self.compute_matches(uri); actions=[]
                for d in diags:
                    for m in matches:
                        if d.get('code')!=m['rc'].id: continue
                        if d.get('range')!=m['diag']['range']: continue
                        for fix in self.fixes_for_match(m):
                            title=fix.get('title') or f"Fix `{m['rc'].id}` with ast-grep"
                            actions.append({"edit":{"changes":{uri:[{"newText":fix['newText'],"range":fix['range']}]}},"isPreferred":True,"kind":"quickfix","title":title})
                self.send_result(mid,actions if actions else None)
            elif method=='workspace/executeCommand':
                command=params.get('command'); args=params.get('arguments') or []
                self.log(f"Running ExecuteCommand {command}",3)
                if command!='ast-grep.applyAllFixes':
                    self.send_result(mid,None); continue
                if not args or not isinstance(args[0],dict):
                    arg=args[0] if args else None
                    if isinstance(arg,str): desc=f'invalid type: string "{arg}", expected struct TextDocumentItem'
                    elif arg is None: desc='invalid type: unit value, expected struct TextDocumentItem'
                    elif isinstance(arg,bool): desc=f'invalid type: boolean `{str(arg).lower()}`, expected struct TextDocumentItem'
                    elif isinstance(arg,(int,float)): desc=f'invalid type: number, expected struct TextDocumentItem'
                    else: desc='invalid type: sequence, expected struct TextDocumentItem'
                    self.log(f"JSON deserialization error: {desc}",1); self.send_result(mid,None); continue
                td=args[0]; uri=td.get('uri')
                if uri:
                    self.docs[uri]={'text':td.get('text',''),'version':td.get('version'),'languageId':td.get('languageId'),'lang':self.lang_from_id(td.get('languageId'),uri)}
                matches=self.compute_matches(uri); edits=[]
                last_end=-1
