                self.shutdown=True; self.send_result(mid,None)
            elif method=='exit':
                return 0 if self.shutdown else 1
            elif method in ('$/cancelRequest',):
                pass
            else:
                if mid is not None:
                    self.send_error(mid,-32601,f"Method not found: {method}")
        return 0

def run_lsp(opts):
    server=LSP(opts)
    return server.run()
