    src=cfg.get('source',''); rewriters=cfg.get('rewriters') or []; join_by=cfg.get('joinBy')
    src_str=str(src); multi=src_str.startswith('$$$'); name=src_str.lstrip('$')
    source_nodes=[]
    if multi:
        source_nodes=list(env.multi.get(name,[]))
    elif name in env.single:
        source_nodes=[env.single[name]]
    elif name in env.transformed:
        return env.transformed[name]
    else:
        return ''
    rw_configs=[]
    for rw_id in rewriters:
        rw=rc.rewriters.get(str(rw_id))
        if rw: rw_configs.append(rw)
    edits=[]; matched_results=[]
    def _fix_template(rw):
        f=rw.get('fix')
        if isinstance(f,str): return f
        if isinstance(f,dict): return f.get('template')
        if isinstance(f,list) and f and isinstance(f[0],dict): return f[0].get('template')
        return None
    for snode in source_nodes:
        for candidate in all_nodes(snode):
            if not candidate.named: continue
            if any(candidate.start>=a and candidate.end<=b for a,b,_ in edits): continue
            for rw in rw_configs:
                try: m=build_matcher(rw.get('rule'), rc.language, rc)
                except Exception: continue
                e=MatchEnv()
                if not m(candidate,e,ctx): continue
                ok=True
                if isinstance(rw.get('constraints'),dict):
                    for cname,crule in rw['constraints'].items():
                        cap=e.single.get(cname)
                        if cap is None: continue
                        cm=build_matcher(crule,rc.language,rc)
