                    tmp_rc=type('Tmp',(),{})(); tmp_rc.transform=rw.get('transform'); tmp_rc.rewriters=rc.rewriters; tmp_rc.language=rc.language
                    try: apply_transforms(tmp_rc,e,ctx,candidate)
                    except Exception: pass
                tmpl=_fix_template(rw)
                if tmpl is not None:
                    repl=substitute_template(str(tmpl),e,candidate,apply_indent=False)
                    edits.append((candidate.start,candidate.end,repl)); matched_results.append(repl)
                break
    if join_by is not None:
        return str(join_by).join(matched_results)
    if not source_nodes: return ''
    first=source_nodes[0]; last=source_nodes[-1]
    base_text=first.doc.text[first.start:last.end]
    # apply edits relative
    out=[]; cursor=first.start
    for a,b,repl in sorted(edits):
        if a<cursor: continue
        out.append(first.doc.text[cursor:a]); out.append(repl); cursor=b
    out.append(first.doc.text[cursor:last.end])
    result=''.join(out)
    from engine import dedent_capture
    return dedent_capture(result, first)

'''
